INSERT INTO public.life_events VALUES ('5bd3f341-bc19-462a-9b50-5ffdc81c3449', 'b2fb1996-e24c-405a-9895-979096e2df22', 'மகிழ்ச்சியான குழந்தைப் பருவம் (Joyful Childhood Memories)', 'குடும்பத்தினருடன் நேரத்தைச் செலவிட்டதும், நண்பர்களுடன் இணைந்து விளையாடியதுமான அழகிய குழந்தைப் பருவ நினைவுகள்.', NULL, NULL, NULL, 'unknown', 'Childhood', NULL, 'confirmed', '2026-10-22 20:34:34.510027+05:30', '2026-10-22 20:34:34.510027+05:30', 'Beautiful childhood memories of spending quality time with family and playing together with friends.', 'Joyful Childhood Memories', 'மகிழ்ச்சியான குழந்தைப் பருவம்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('ba147fe5-6bff-42f5-926c-118995045c20', '11111111-1111-4111-a111-111111111111', 'முதல் ஆசிரியர் பணி (First Teaching Job)', '1972 ஆம் ஆண்டு திப் சிட்டி பாளையத்தில் முதல்முறையாக ஆசிரியர் பணியில் சேர்ந்தது.', NULL, 1972, NULL, 'approximate', 'Career', 'Erode', 'confirmed', '2026-10-15 18:10:26.896+05:30', '2026-10-15 18:10:26.896+05:30', 'In the year 1972, I joined the teaching profession for the first time in the Tip City Palayam.', 'First Teaching Job', 'முதல் ஆசிரியர் பணி') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('2fd80a2f-a6e5-4cb6-b722-19aa3b0980dd', '9a064be3-6c1b-4383-a5a9-ec80d5dd5684', 'வளர்த்த ஊரின் அமைதி (Peaceful Upbringing)', 'வளர்ந்த ஊர் மிகவும் அழகானதும் அமைதியானதுமாக இருந்தது.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Bhavani', 'unreviewed', '2026-10-15 18:01:27.841+05:30', '2026-10-15 18:01:27.841+05:30', 'The town was very beautiful and peaceful.', 'Peaceful Upbringing', 'வளர்த்த ஊரின் அமைதி') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('73981946-8499-4fd3-90c3-df8af7dd5f23', '9a064be3-6c1b-4383-a5a9-ec80d5dd5684', 'அன்பான குடும்பச் சூழல் (Loving Family Environment)', 'எங்கள் வீடு அன்பும் மகிழ்ச்சியும் நிறைந்தது.', NULL, NULL, NULL, 'unknown', 'Family', 'Bhavani', 'unreviewed', '2026-10-15 18:01:27.844+05:30', '2026-10-15 18:01:27.844+05:30', 'Our home is filled with love and laughter.', 'Loving Family Environment', 'அன்பான குடும்பச் சூழல்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('fde17114-1cde-469e-819a-54e3bc75b55c', '11111111-1111-4111-a111-111111111111', 'திப் சிட்டி பாளையத்தில் நீண்டகாலப் பணி (Long-term Service in Thippa City Palayam)', 'கௌந்தப்பாடிக்குப் பிறகு மீண்டும் திப் சிட்டி பாளையத்திற்கே திரும்பி அங்கு 32 ஆண்டுகள் பணிபுரிந்தது.', NULL, NULL, NULL, 'unknown', 'Career', 'Erode', 'confirmed', '2026-10-15 18:10:26.9+05:30', '2026-10-15 18:10:26.9+05:30', 'After Goundapadi, he returned to Dibb City Palayam and worked there for 32 years.', 'Long-term Service in Thippa City Palayam', 'திப் சிட்டி பாளையத்தில் நீண்டகாலப் பணி') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('fab0793b-efa4-4140-9c95-82a06c35b6ec', '11111111-1111-4111-a111-111111111111', 'தாயக்கரம் விளையாடுதல் (Playing Thayam (Traditional Game))', 'மே மாத பள்ளி விடுமுறையின் போது மட்டுமே தாயக்கரம் விளையாடும் வழக்கம் இருந்தது.', NULL, NULL, NULL, 'unknown', 'Tradition', 'Erode', 'confirmed', '2026-10-16 08:21:03.416+05:30', '2026-10-16 08:21:03.416+05:30', 'The habit of playing the traditional game Thayam, which was only played during the May school holidays.', 'Playing Thayam (Traditional Game)', 'தாயக்கரம் விளையாடுதல்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('f6041a48-d737-4b55-9a04-a30385b9cbf4', '11111111-1111-4111-a111-111111111111', 'சிஎஸ்ஐ பள்ளிக்கூடத்தில் கல்வி (Education at CSI School)', 'சிஎஸ்ஐ பள்ளிக்கூடத்தில் ஒன்றாம் வகுப்பு முதல் ஐந்தாம் வகுப்பு வரை படித்தது.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-15 18:10:26.889+05:30', '2026-10-15 18:10:26.889+05:30', 'CSI studied from first to fifth standard in school.', 'Education at CSI School', 'சிஎஸ்ஐ பள்ளிக்கூடத்தில் கல்வி') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('a0f334e7-5735-4858-86b1-ef79abbfe457', '11111111-1111-4111-a111-111111111111', 'உயர்நிலைப் பள்ளிக் கல்வி (Secondary School Education)', 'பாய்ஸ் ஹை ஸ்கூல் மற்றும் கேர்ள்ஸ் ஹை ஸ்கூலில் இணைந்து பயின்றது.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-15 18:10:26.892+05:30', '2026-10-15 18:10:26.892+05:30', 'Boys studied together with the girls at the High School and the High School for Girls.', 'Secondary School Education', 'உயர்நிலைப் பள்ளிக் கல்வி') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('0d684974-de58-47f0-8e03-a656276f15b1', '11111111-1111-4111-a111-111111111111', 'ஆசிரியர் பயிற்சி (Teacher Training)', 'பதினொன்றாம் வகுப்பு முடித்தவுடன் ஈரோட்டில் உள்ள ஜிடிஎஸ்-இல் இரண்டு ஆண்டுகள் ஆசிரியர் பயிற்சி மேற்கொண்டது.', NULL, NULL, NULL, 'unknown', 'Career', 'Erode', 'confirmed', '2026-10-15 18:10:26.894+05:30', '2026-10-15 18:10:26.894+05:30', 'After completing her 11th standard, she underwent two years of teacher training at GDS in Erode.', 'Teacher Training', 'ஆசிரியர் பயிற்சி') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('c4f8c367-f157-4a48-a331-345c4908f71c', '11111111-1111-4111-a111-111111111111', 'கௌந்தப்பாடியில் பணி (Work in Kaunthapadi)', 'பவானிக்கு மாற முயன்று கிடைக்காததால், கௌந்தப்பாடியில் சுமார் ஏழு ஆண்டுகள் பணிபுரிந்தது.', NULL, NULL, NULL, 'unknown', 'Career', 'Erode', 'confirmed', '2026-10-15 18:10:26.898+05:30', '2026-10-15 18:10:26.898+05:30', 'Unsuccessful in her attempts to get Bhavani, she worked for about seven years in Gowndapadi.', 'Work in Kaunthapadi', 'கௌந்தப்பாடியில் பணி') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('bc1e561d-d37e-477e-b89b-b9a07ed87623', '11111111-1111-4111-a111-111111111111', 'ஹை ஸ்கூல் ஆசிரியர்களின் நல்ல நடத்தை (Good Conduct of High School Teachers)', 'உயர்நிலைப் பள்ளியில் (ஹை ஸ்கூல்) ஆசிரியர்கள் அனைவரும் மிகவும் நல்ல முறையில் நடந்து கொண்டார்கள்.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-15 18:10:26.918+05:30', '2026-10-15 18:10:26.918+05:30', 'The teachers in high school (high school) were very good.', 'Good Conduct of High School Teachers', 'ஹை ஸ்கூல் ஆசிரியர்களின் நல்ல நடத்தை') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('f91a2fa7-cb70-482a-9a00-ba3dc134fdb8', '11111111-1111-4111-a111-111111111111', 'பவானியில் உள்ள வீடும் பள்ளிக்கூடப் பயணமும் (Home in Bhavani and School Journey)', 'பவானி பழனிபுரம் கவுண்ட தெருவில் உள்ள சால வீட்டில் வசித்ததும், பள்ளிக்கு நடந்து சென்று மதிய உணவுக்காக வீடு திரும்பியதும்.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-15 18:10:26.902+05:30', '2026-10-15 18:10:26.902+05:30', 'Bhavani lived in a house on Gounder Street in Palani Pazhanipuram, and walked to school and returned home for lunch.', 'Home in Bhavani and School Journey', 'பவானியில் உள்ள வீடும் பள்ளிக்கூடப் பயணமும்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('91138059-3d45-4dda-92f5-fa4d1571e7a9', '11111111-1111-4111-a111-111111111111', 'வீட்டு வேலைகளில் அம்மாவிற்கு உதவுதல் (Helping Mother with Household Chores)', 'அம்மாவிற்கு உதவியாக வீட்டின் அனைத்து வேலைகளையும் செய்து கொடுத்துவிட்டு பள்ளிக்குச் சென்றது.', NULL, NULL, NULL, 'unknown', 'Family', 'Erode', 'confirmed', '2026-10-15 18:10:26.904+05:30', '2026-10-15 18:10:26.904+05:30', 'She went to school after helping her mother with all the housework.', 'Helping Mother with Household Chores', 'வீட்டு வேலைகளில் அம்மாவிற்கு உதவுதல்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('748d4b7a-9f81-4fca-9d52-f50d88e17bc0', '11111111-1111-4111-a111-111111111111', 'பெற்றோரின் அன்பும் அரவணைப்பும் (Parents'' Love and Care)', 'அம்மா அப்பா தங்களை எங்கும் தனியாக அனுப்பாமல், தங்கள் தேவைகளை தாங்களே நிறைவேற்றிக் கொடுத்து, எப்போதும் தங்கள் அருகிலேயே வைத்திருந்தனர்.', NULL, NULL, NULL, 'unknown', 'Family', 'Erode', 'confirmed', '2026-10-15 18:10:26.909+05:30', '2026-10-15 18:10:26.909+05:30', 'Mothers and fathers did not send them away alone, but always stayed close by, giving them their needs.', 'Parents'' Love and Care', 'பெற்றோரின் அன்பும் அரவணைப்பும்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('0127c41f-57d8-4ce4-9f49-c26d7fd5a9e5', '9a064be3-6c1b-4383-a5a9-ec80d5dd5684', 'சிறுவயது மகிழ்ச்சி (Childhood Happiness)', 'சிறு வயதில் நண்பர்களுடன் விளையாடுவதும், குடும்பத்தினருடன் நேரம் செலவிடுவதும் மிகுந்த மகிழ்ச்சியை அளித்தது.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Bhavani', 'confirmed', '2026-10-15 17:16:34.153+05:30', '2026-10-15 17:24:57.284+05:30', 'Playing with friends and spending time with family was very enjoyable when I was a child.', 'Childhood Happiness', 'சிறுவயது மகிழ்ச்சி') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('b876fa60-b383-4dd0-9a5f-878877059666', '11111111-1111-4111-a111-111111111111', 'உடன்பிறப்புகளின் கல்வி மற்றும் வேலை (Siblings'' Education and Employment)', 'இரண்டு அண்ணன்களும் வங்கி மற்றும் உயர்நிலைப் பள்ளியில் வேலை பார்த்தனர், தங்கச்சி சேலத்தில் வசிக்கிறார்.', NULL, NULL, NULL, 'unknown', 'Family', 'Erode', 'confirmed', '2026-10-15 18:10:26.911+05:30', '2026-10-15 18:10:26.911+05:30', 'Both the brothers worked in a bank and a high school, while her sister lives in Salem.', 'Siblings'' Education and Employment', 'உடன்பிறப்புகளின் கல்வி மற்றும் வேலை') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('9329afb5-a3a8-43aa-9607-13990d6b7fad', '11111111-1111-4111-a111-111111111111', 'பள்ளிக்கு ஒன்றாகச் சென்றது மற்றும் தங்கச்சியின் கல்வி (Going to School Together and Younger Sister''s Education)', 'பேசும் நபர் மற்றும் தங்கச்சி இருவரும் ஒன்றாகப் பள்ளிக்குச் சென்றனர், ஆனால் தங்கச்சிக்குத் தொடர்ந்து படிக்க இடமில்லாமல் வேலைக்குச் செல்லவில்லை.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-15 18:10:26.913+05:30', '2026-10-15 18:10:26.913+05:30', 'The speaker also mentions that their sister went to school together with them, but their sister didn''t continue her studies and went to work.', 'Going to School Together and Younger Sister''s Education', 'பள்ளிக்கு ஒன்றாகச் சென்றது மற்றும் தங்கச்சியின் கல்வி') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('d5c5a8f4-b382-43c4-b8a0-180ff706ef71', '11111111-1111-4111-a111-111111111111', 'கிணற்றில் தண்ணீர் கொண்டு வருதல் (Fetching Water from the Well)', 'பள்ளி முடிந்து வீடு திரும்பியதும், அம்மாவுக்குத் தண்ணீர் தேவைப்பட்டதால் கிணற்றுக்குச் சென்று தண்ணீர் எடுத்து வந்து ஊற்றி வைப்பது.', NULL, NULL, NULL, 'unknown', 'Family', 'Erode', 'confirmed', '2026-10-15 18:10:26.915+05:30', '2026-10-15 18:10:26.915+05:30', 'After finishing school and returning home, since mother needed water, she went to the well, fetched water, brought it, and poured it.', 'Fetching Water from the Well', 'கிணற்றில் தண்ணீர் கொண்டு வருதல்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('da4d3ecb-6f8a-48d6-88d9-b88eb7be5d60', '11111111-1111-4111-a111-111111111111', 'சிஎஸ்ஐ பள்ளிக்கூடத்தில் ஆசிரியரின் கண்டிப்பு (Teacher''s Strictness at CSI School)', 'நான்காம் வகுப்பு வாத்தியார் ஞானசுந்தரம், தனது அண்ணனின் திருமணத்திற்கு லீவ் எடுக்க முடியாததால், குச்சியால் தலையில் அடித்த சம்பவம்.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-15 18:10:26.916+05:30', '2026-10-15 18:10:26.916+05:30', 'The incident of Gnanasundaram, the fourth-grade teacher, hitting his head with a stick because he couldn''t take leave for his brother''s wedding.', 'Teacher''s Strictness at CSI School', 'சிஎஸ்ஐ பள்ளிக்கூடத்தில் ஆசிரியரின் கண்டிப்பு') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('ab947dfa-d838-4130-9270-062765e8c48c', '11111111-1111-4111-a111-111111111111', 'சிஎஸ்ஐ பள்ளிக்கூடத்தில் ஆரம்பக் கல்வி (Elementary Education at CSI School)', 'ஐந்தாம் வகுப்பு வரை சிஎஸ்ஐ பள்ளிக்கூடத்தில் படித்த அனுபவம்.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-15 18:10:26.917+05:30', '2026-10-15 18:10:26.917+05:30', 'Experience of studying in CSI school up to fifth standard.', 'Elementary Education at CSI School', 'சிஎஸ்ஐ பள்ளிக்கூடத்தில் ஆரம்பக் கல்வி') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('276ad46c-2a15-4f84-b0a2-60ff6bdb5d91', '11111111-1111-4111-a111-111111111111', 'பள்ளி நண்பர்கள் (School Friends)', 'பாலிகார நண்பர்களான சுபத்ரா மற்றும் சரோஜினி டீச்சர்களின் இறப்பு மற்றும் அவர்களின் குழந்தைகளின் தற்போதைய நிலை.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-15 18:10:26.919+05:30', '2026-10-15 18:10:26.919+05:30', 'The death of Palikar''s friends Subhadra and Sarojini teachers and the present condition of their children.', 'School Friends', 'பள்ளி நண்பர்கள்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('3f753181-47a9-4ef6-86ad-215d2b2948c8', '11111111-1111-4111-a111-111111111111', 'ஈஸ்வரியின் திருமணம் (Eswari''s Marriage)', 'ஈஸ்வரி என்ற பெண் காளிங்கராயம்பாளையத்தில் திருமணம் செய்து கொடுக்கப்பட்டு, அங்குள்ள பவானிக்கு அருகில் வசிக்கிறார்.', NULL, NULL, NULL, 'unknown', 'Marriage', 'Erode', 'confirmed', '2026-10-15 18:10:26.922+05:30', '2026-10-15 18:10:26.922+05:30', 'Eshwari, a woman married to Kalingarayampalayam, lives near Bhavani.', 'Eswari''s Marriage', 'ஈஸ்வரியின் திருமணம்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('551fa2f5-9a07-4f3c-b723-d208415ffca3', '11111111-1111-4111-a111-111111111111', 'மே மாத விடுமுறையில் தாயக்கர் விளையாட்டு (Playing Thayyakar during May Holidays)', 'மே மாத விடுமுறையின் போது மட்டுமே பாரம்பரிய விளையாட்டான தாயக்கர் விளையாடினர்.', NULL, NULL, NULL, 'unknown', 'Tradition', 'Erode', 'confirmed', '2026-10-15 18:10:26.908+05:30', '2026-10-15 18:10:26.908+05:30', 'The traditional sport of Thaayakkar was played only during the month of May.', 'Playing Thayyakar during May Holidays', 'மே மாத விடுமுறையில் தாயக்கர் விளையாட்டு') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('26607a2d-72ce-49cc-8dc5-e5f23ec2b7af', '9a064be3-6c1b-4383-a5a9-ec80d5dd5684', 'அமைதியான கிராமப்புற வளர்ப்பு (Upbringing in a Peaceful Village)', 'அவர் வளர்ந்த ஊர் மிகவும் அழகானதும் அமைதியானதுமாகும்; அங்கு வீடு அன்பும் மகிழ்ச்சியும் நிறைந்து காணப்பட்டது.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Bhavani', 'confirmed', '2026-10-15 17:16:34.155+05:30', '2026-10-15 17:24:58.735+05:30', 'His childhood home was a very beautiful and peaceful place, where love and happiness were abundant.', 'Upbringing in a Peaceful Village', 'அமைதியான கிராமப்புற வளர்ப்பு') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('795dd2c8-dc3e-489b-8367-87dcdcc67b69', '11111111-1111-4111-a111-111111111111', 'புருஷாமலையிலிருந்து பவானிக்கு இடம்பெயர்வு (Migration from Purushamalam to Bhavani)', 'குழந்தை பருவத்தில் புருஷாமலையிலிருந்து பவானிக்கு குடும்பத்துடன் இடம்பெயர்ந்தது.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-15 18:10:26.882+05:30', '2026-10-15 18:10:26.882+05:30', 'During her childhood, the family moved from Purushamali to Bhavani.', 'Migration from Purushamalam to Bhavani', 'புருஷாமலையிலிருந்து பவானிக்கு இடம்பெயர்வு') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('1d7ea9f7-7f3d-4a61-980f-b825eb5792da', '11111111-1111-4111-a111-111111111111', 'வீட்டு வேலைகளில் உதவுதல் (Helping with Household Chores)', 'சிறுவயதில் வீட்டை விட்டு வெளியே செல்லாமல், அம்மாவுக்கு உதவியாகவும் அப்பாவிற்கு துணையாகவும் வீட்டில் இருந்தனர்; தங்கச்சியுடன் சேர்ந்து வீட்டு வேலைகளில் ஈடுபட்டனர்.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-15 18:10:26.906+05:30', '2026-10-15 18:10:26.906+05:30', 'As a child, she stayed home without leaving the house to help her mother and to help her father; she also did housework along with her sister.', 'Helping with Household Chores', 'வீட்டு வேலைகளில் உதவுதல்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('a8c089cd-aa0c-49b6-a124-15edb60cc2ec', '11111111-1111-4111-a111-111111111111', 'பள்ளிக்கு நடந்து செல்வதும், சீமென் விளக்கில் படிப்பது (Walking to School and Studying by a Cement Lamp)', 'பள்ளிக்கு நடந்து சென்று, மதிய உணவுக்காக வீட்டிற்குத் திரும்பி, மீண்டும் மாலை வரைப் பள்ளிக்குச் சென்று, வீட்டில் மின்சாரம் இல்லாததால் சீமென் விளக்கில் படித்தது.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-15 18:10:26.914+05:30', '2026-10-15 18:10:26.914+05:30', 'Walking to school, returning home for lunch, and then going back to school until evening, and studying under a candle lamp because there was no electricity at home.', 'Walking to School and Studying by a Cement Lamp', 'பள்ளிக்கு நடந்து செல்வதும், சீமென் விளக்கில் படிப்பது') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('4213867d-4394-4ba5-8c58-fe317255a330', '11111111-1111-4111-a111-111111111111', 'ருக்மணியின் வாழ்க்கை (Rukmani''s Life)', 'பாலிகார தோழியான ருக்மணி காளிங்கராயம்பாளையத்தைச் சேர்ந்தவர், ஆசிரியர் பயிற்சி முடித்து கோயம்புத்தூரில் ஆசிரியராகப் பணியாற்றி ஓய்வு பெற்றார்.', NULL, NULL, NULL, 'unknown', 'Family', 'Erode', 'confirmed', '2026-10-15 18:10:26.921+05:30', '2026-10-15 18:10:26.921+05:30', 'Rukmani Kalingarayampalayam, a friend of Palikar, completed her teacher training and retired after working as a teacher in Coimbatore.', 'Rukmani''s Life', 'ருக்மணியின் வாழ்க்கை') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('a1f3ac22-de49-4d46-a0aa-70a11dc98bfd', '11111111-1111-4111-a111-111111111111', 'புருஷாமலத்திலிருந்து பவானிக்கு இடம்பெயர்வு (Migration from Purushamala to Bhavani)', 'ராஜேஸ்வரி தனது குழந்தைப் பருவத்தில் புருஷாமலத்திலிருந்து பவானிக்கு குடிபெயர்ந்தார்.', NULL, 1972, NULL, 'year', 'Childhood', 'Erode', 'confirmed', '2026-10-16 08:21:03.387+05:30', '2026-10-16 08:21:03.387+05:30', 'Rajeshwari migrated from Purushamala to Bhavani during her childhood.', 'Migration from Purushamala to Bhavani', 'புருஷாமலத்திலிருந்து பவானிக்கு இடம்பெயர்வு') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('d0d9f20e-7b07-4b9c-9803-2d7aaa12b925', '11111111-1111-4111-a111-111111111111', 'பள்ளிக் கல்வி (School Education)', 'சிஎஸ்ஐ பள்ளிக்கூடத்தில் ஒன்றாம் வகுப்பு முதல் ஐந்தாம் வகுப்பு வரை படித்தார். பின்னர் பாய்ஸ் ஹை ஸ்கூல் மற்றும் கேர்ள்ஸ் ஹை ஸ்கூலில் இணைந்து படித்தார்.', NULL, 1972, NULL, 'year', 'Childhood', 'Erode', 'confirmed', '2026-10-16 08:21:03.394+05:30', '2026-10-16 08:21:03.394+05:30', 'Studied from first to fifth grade at CSI School, and later attended Boys High School and Girls High School.', 'School Education', 'பள்ளிக் கல்வி') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('d90464a6-e54d-4b2c-8c37-3a343f50c30c', '11111111-1111-4111-a111-111111111111', 'திப் சிட்டி பாளையத்தில் முதல் பணி (First Posting in Thippa City Palayam)', 'ஆரம்பத்தில் திப் சிட்டி பாளையத்தில் ஆசிரியராகப் பணியாற்றினார்.', NULL, 1972, NULL, 'year', 'Career', 'Erode', 'confirmed', '2026-10-16 08:21:03.4+05:30', '2026-10-16 08:21:03.4+05:30', 'Worked as a teacher for the first time in Thippa City Palayam.', 'First Posting in Thippa City Palayam', 'திப் சிட்டி பாளையத்தில் முதல் பணி') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('0b5eaf2e-b7e6-4204-a93a-f8ffe0d587d9', '11111111-1111-4111-a111-111111111111', 'கவுந்தப்பாடியில் பணி (Work in Kavunthapadi)', 'ஏழு வருடங்கள் கவுந்தப்பாடியில் ஆசிரியராகப் பணியாற்றினார்.', NULL, 1972, NULL, 'year', 'Career', 'Erode', 'confirmed', '2026-10-16 08:21:03.402+05:30', '2026-10-16 08:21:03.402+05:30', 'Worked as a teacher in Kavunthapadi for seven years.', 'Work in Kavunthapadi', 'கவுந்தப்பாடியில் பணி') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('52d52c5e-2818-4ea5-acba-086d62aaa9f2', '11111111-1111-4111-a111-111111111111', 'பவானியில் பணி முயற்சி (Attempt for Bhavani Posting)', 'பவானியில் பணி பெற முயன்று கிடைக்காததால் மீண்டும் திப் சிட்டி பாளையத்திற்கே திரும்பினார்.', NULL, 1972, NULL, 'year', 'Career', 'Erode', 'confirmed', '2026-10-16 08:21:03.407+05:30', '2026-10-16 08:21:03.407+05:30', 'Attempted to get a posting in Bhavani but did not receive it, returning to Thippa City Palayam.', 'Attempt for Bhavani Posting', 'பவானியில் பணி முயற்சி') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('cdef1d2e-4d23-4548-b2e5-db924acbbabf', '11111111-1111-4111-a111-111111111111', 'பவானியில் உள்ள வீட்டிலும் ஆற்றுப் பக்கத்திலும் வளர்ந்தது (Growing up in the house and by the river in Bhavani)', 'பவானி பழனிபுரம் கவுண்ட தெருவில் மூன்றாவது தெருவில் இருந்த சால வீட்டில் வளர்ந்ததும், ஆற்றுப் பக்கத்தில் இருந்த வீட்டின் நினைவுகளும்.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-16 08:21:03.412+05:30', '2026-10-16 08:21:03.412+05:30', 'Recalling living in a thatched house on the third street in Palanipuram Gounder Street, Bhavani, and the memories associated with the river beside the house.', 'Growing up in the house and by the river in Bhavani', 'பவானியில் உள்ள வீட்டிலும் ஆற்றுப் பக்கத்திலும் வளர்ந்தது') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('b6c91f14-d7d0-4a9d-82a8-654809d42331', '11111111-1111-4111-a111-111111111111', 'பள்ளிக்கு நடந்து செல்வதும் மதிய உணவு வழக்கமும் (Walking to school and the afternoon meal routine)', 'அம்மாவுக்கு உதவியாக வீட்டு வேலைகள் செய்துவிட்டு பள்ளிக்கு நடந்து செல்வதும், மதிய உணவுக்கு வீட்டில் சமைத்ததை சாப்பிட்டுவிட்டு மீண்டும் பள்ளிக்குத் திரும்புவதும்.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-16 08:21:03.413+05:30', '2026-10-16 08:21:03.413+05:30', 'Helping their mother with household chores before walking to school, eating the lunch prepared at home, and returning to school at 1:45 PM.', 'Walking to school and the afternoon meal routine', 'பள்ளிக்கு நடந்து செல்வதும் மதிய உணவு வழக்கமும்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('a0c4df9a-e257-4286-8ce9-4049f00d3863', '11111111-1111-4111-a111-111111111111', 'பெற்றோரின் அன்பும் பாதுகாப்பும் (Parents'' Affection and Protection)', 'அம்மா அப்பா தங்களை எங்கும் தனியாக அனுப்பாமல், தங்கள் தேவைகளைத் தாங்களே பூர்த்தி செய்து கொடுத்தனர்.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-16 08:21:03.418+05:30', '2026-10-16 08:21:03.418+05:30', 'Her parents showed great affection and did not send her anywhere or to anyone else''s house, fulfilling all her needs themselves.', 'Parents'' Affection and Protection', 'பெற்றோரின் அன்பும் பாதுகாப்பும்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('1916663d-f16d-4530-a1fe-6fc7fa6d1511', '11111111-1111-4111-a111-111111111111', 'அப்பாவுடன் இருந்த நெருக்கம் (Closeness with Father)', 'அப்பா அவளின் மீது மிகுந்த அன்பு வைத்திருந்தார்.', NULL, NULL, NULL, 'unknown', 'Family', 'Erode', 'confirmed', '2026-10-16 08:21:03.419+05:30', '2026-10-16 08:21:03.419+05:30', 'Her father had a lot of affection for her.', 'Closeness with Father', 'அப்பாவுடன் இருந்த நெருக்கம்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('7654d6d3-d416-48be-b3b1-af75b3347512', '11111111-1111-4111-a111-111111111111', 'அம்மா அப்பாவின் தினசரி வருகை (Daily Return of Parents)', 'எங்கு சென்றாலும், காலை சென்று மாலை திரும்பி வருவார்கள்.', NULL, NULL, NULL, 'unknown', 'Family', 'Erode', 'confirmed', '2026-10-16 08:21:03.423+05:30', '2026-10-16 08:21:03.423+05:30', 'Wherever they went, her parents would leave in the morning and return by the evening.', 'Daily Return of Parents', 'அம்மா அப்பாவின் தினசரி வருகை') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('7ab11add-832b-48ce-beab-043d7c080d9d', '11111111-1111-4111-a111-111111111111', 'தங்கச்சியுடன் பள்ளிப் பயணம் (School Journey with Younger Sister)', 'ராஜேஸ்வரியும் அவரது தங்கச்சியும் ஒன்றாகப் பள்ளிக்குச் சென்றனர், ஒன்றாகவே வீடு திரும்பினர்.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-16 08:21:03.429+05:30', '2026-10-16 08:21:03.429+05:30', 'Rajeshwari and her younger sister went to school together and returned home together.', 'School Journey with Younger Sister', 'தங்கச்சியுடன் பள்ளிப் பயணம்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('975ebdda-f0a4-45ea-86d7-db402bb92521', '11111111-1111-4111-a111-111111111111', 'தங்கச்சியின் கல்வி மற்றும் வசிப்பிடம் (Younger Sister''s Education and Residence)', 'ராஜேஸ்வரி படித்ததால் தங்கச்சிக்கு படிக்க இடம் கிடைக்கவில்லை, மேலும் அவர் வேலைக்குச் செல்லவில்லை; தற்போது சேலத்தில் வசிக்கிறார்.', NULL, NULL, NULL, 'unknown', 'Family', 'Erode', 'confirmed', '2026-10-16 08:21:03.43+05:30', '2026-10-16 08:21:03.43+05:30', 'Because Rajeshwari got to study, her younger sister did not get the opportunity to study or go to work, and currently resides in Salem.', 'Younger Sister''s Education and Residence', 'தங்கச்சியின் கல்வி மற்றும் வசிப்பிடம்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('b38dce80-0553-44ad-95f1-1d57bd348465', '11111111-1111-4111-a111-111111111111', 'பள்ளிப் பயணமும் அன்றாட வழக்கமும் (School Journey and Daily Routine)', 'பள்ளிக்கு நடந்து சென்று, மதிய உணவிற்காக வீடு திரும்பி, மீண்டும் மதியம் பள்ளிக்குச் சென்று மாலை வீடு திரும்புதல்.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-16 08:21:03.432+05:30', '2026-10-16 08:21:03.432+05:30', 'Walking to school, returning home for lunch, going back to school in the afternoon, and returning home in the evening.', 'School Journey and Daily Routine', 'பள்ளிப் பயணமும் அன்றாட வழக்கமும்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('ca7ee74a-a741-432a-aa68-f9a2a4c92bff', '11111111-1111-4111-a111-111111111111', 'அம்மாவுக்கு உதவுதல் (Helping Mother)', 'கிணற்றுக்குச் சென்று தண்ணீர் எடுத்து வந்து அம்மாவுக்கு ஊற்றி வைப்பது.', NULL, NULL, NULL, 'unknown', 'Family', 'Erode', 'confirmed', '2026-10-16 08:21:03.433+05:30', '2026-10-16 08:21:03.433+05:30', 'Fetching water from the well and pouring it for their mother.', 'Helping Mother', 'அம்மாவுக்கு உதவுதல்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('b6664115-09ab-4a0a-8175-a01f32d833a0', '11111111-1111-4111-a111-111111111111', 'பாலிகார நண்பர்கள் (Childhood Friends)', 'பாலிகார நண்பரான சுபத்ரா டீச்சர் மற்றும் சரோஜினி டீச்சர் ஆகியோரை நினைவு கூர்கிறார். மேலும், காளிங்கராயம்பாளையத்தைச் சேர்ந்த ருக்மணி என்ற தோழியைப் பற்றியும் குறிப்பிடுகிறார்.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-16 08:21:03.443+05:30', '2026-10-16 08:21:03.443+05:30', 'Recalls childhood friends Subathra Teacher and Sarojini Teacher who have passed away. Also mentions a friend named Rukmani from Kalangrayampalayam.', 'Childhood Friends', 'பாலிகார நண்பர்கள்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('55fbc653-17b2-4ad3-9631-458d649cd92d', '11111111-1111-4111-a111-111111111111', 'ருக்மணியின் வாழ்க்கை மற்றும் திருமணம் (Rukmani''s Life and Marriage)', 'ருக்மணி என்ற தோழி ஆசிரியர் பயிற்சி முடித்து கோயம்புத்தூரில் ஆசிரியராகப் பணியாற்றி ஓய்வு பெற்றார். பின்னர் ஈஸ்வரி என்ற பெண்ணை காளிங்கராயம்பாளையத்தில் திருமணம் செய்து கொடுத்து அங்கேயே குடியேறினார்.', NULL, NULL, NULL, 'unknown', 'Family', 'Erode', 'confirmed', '2026-10-16 08:21:03.445+05:30', '2026-10-16 08:21:03.445+05:30', 'The friend Rukmani completed teacher training, worked as a teacher in Coimbatore, and retired. She later married a woman named Eswari in Kalangrayampalayam and settled there.', 'Rukmani''s Life and Marriage', 'ருக்மணியின் வாழ்க்கை மற்றும் திருமணம்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('61c51bf2-bbe3-41ac-80d2-47a5b4facc0d', '11111111-1111-4111-a111-111111111111', 'சீமென் விளக்கில் படித்தல் (Studying by Cement Lamp)', 'வீட்டில் மின்சார வசதி இல்லாததால், சீமென் விளக்கை பயன்படுத்திப் படிப்பது.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-16 08:21:03.435+05:30', '2026-10-16 08:21:03.435+05:30', 'Studying using a cement lamp at home due to the lack of electricity.', 'Studying by Cement Lamp', 'சீமென் விளக்கில் படித்தல்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('4150075f-b361-4ede-a3ed-dc2a4ae24988', '11111111-1111-4111-a111-111111111111', 'அண்ணன் திருமணத்தின் போது ஆசிரியரின் கண்டிப்பு (Teacher''s Strictness During Brother''s Wedding)', 'பள்ளியில் நான்காம் வகுப்பு ஆசிரியரான ஞானசுந்தரம், மாணவியின் அண்ணன் திருமணத்திற்காக விடுப்பு எடுத்தபோது, அவர் திரும்பி வரமாட்டாரா என்று கோபத்துடன் கேட்டார். பின்னர் மாணவியின் தலையில் குச்சியால் அடித்தார்.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-16 08:21:03.437+05:30', '2026-10-16 08:21:03.437+05:30', 'Fourth-grade teacher Gnanasundaram took issue with the student taking leave for her brother''s wedding. When she explained she couldn''t attend because of the wedding, he struck her on the head with a stick.', 'Teacher''s Strictness During Brother''s Wedding', 'அண்ணன் திருமணத்தின் போது ஆசிரியரின் கண்டிப்பு') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('d598e823-5e08-4380-9276-14dc637b3d8a', '11111111-1111-4111-a111-111111111111', 'பள்ளிப் படிப்பும் ஆசிரியர்களின் தாக்கமும் (Schooling and Teachers'' Impact)', 'ஐந்தாம் வகுப்பு வரை சிஎஸ்ஐ தொடக்கப் பள்ளியில் படித்தார். அங்கு ஆசிரியர்கள் அனைவரும் நல்ல முறையில் பாடம் நடத்திக் கொடுத்தனர். உயர்நிலைப் பள்ளியில் ஆசிரியர்கள் நல்ல முறையில் நடந்து கொண்டனர்.', NULL, NULL, NULL, 'unknown', 'Childhood', 'Erode', 'confirmed', '2026-10-16 08:21:03.441+05:30', '2026-10-16 08:21:03.441+05:30', 'Studied up to fifth grade at a CSI elementary school where all teachers taught well. In high school, the teachers behaved very well.', 'Schooling and Teachers'' Impact', 'பள்ளிப் படிப்பும் ஆசிரியர்களின் தாக்கமும்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('4c1502c3-fdbb-4518-b875-1339e56d4ead', '11111111-1111-4111-a111-111111111111', 'ஆசிரியப் பணி தொடக்கம் (Beginning of Teaching Career)', '1972 ஆம் ஆண்டில் தனது ஆசிரியர் பணியைத் தொடங்கினார்.', NULL, 1972, NULL, 'year', 'Career', 'Erode', 'confirmed', '2026-10-16 08:21:03.397+05:30', '2026-10-16 08:21:03.397+05:30', 'Began her teaching career in 1972.', 'Beginning of Teaching Career', 'ஆசிரியப் பணி தொடக்கம்') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('f9d3c9e8-5e83-400e-8c80-5507be76939a', '11111111-1111-4111-a111-111111111111', 'சகோதரர்களுடனான உறவு (Relationship with Brothers)', 'இரண்டு அண்ணன்கள் தமக்கு மூத்தவர்கள் என்றும், அவர்கள் இருவரும் படிப்பை முடித்து வேலை பார்த்தனர் என்றும் ராஜேஸ்வரி கூறுகிறார்.', NULL, NULL, NULL, 'unknown', 'Family', 'Erode', 'confirmed', '2026-10-16 08:21:03.425+05:30', '2026-10-16 08:21:03.425+05:30', 'Rajeshwari mentions that she had two elder brothers who completed their studies and were employed.', 'Relationship with Brothers', 'சகோதரர்களுடனான உறவு') ON CONFLICT DO NOTHING;
INSERT INTO public.life_events VALUES ('739f5b9f-0d80-4ccf-8744-e505bb03c384', '11111111-1111-4111-a111-111111111111', 'அண்ணன்களின் வேலைகள் (Brothers'' Occupations)', 'ஒரு அண்ணன் நில அடமான வங்கியில் செயலாளராகவும், மற்றொரு அண்ணன் உயர்நிலைப் பள்ளியில் எழுத்தராகவும் பணிபுரிந்தனர்.', NULL, NULL, NULL, 'unknown', 'Career', 'Erode', 'confirmed', '2026-10-16 08:21:03.427+05:30', '2026-10-16 08:21:03.427+05:30', 'One brother worked as a secretary in a land mortgage bank and the other as a clerk in a high school.', 'Brothers'' Occupations', 'அண்ணன்களின் வேலைகள்') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('d542c2a8-2bde-4089-a271-236260ebc205', 'Childhood', 'Early Years', 'உங்கள் குழந்தைப் பருவத்தைப் பற்றி சொல்ல முடியுமா?', 'Could you tell me about your childhood?', 1, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('82665ab5-dfa8-4efa-b5ba-2a27527a66b5', 'Childhood', 'Early Years', 'நீங்கள் வளர்ந்த ஊர் மற்றும் வீட்டைப் பற்றி விவரியுங்கள்.', 'Describe the town and home you grew up in.', 2, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('c5e2b3ea-7a00-40fc-b9e7-bd691c8c9505', 'Career', 'Adult', 'உங்கள் முதல் வேலை அல்லது தொழில் அனுபவம் எவ்வாறு தொடங்கியது?', 'How did your first job or career experience begin?', 10, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('9c84a68e-ec53-47ff-887d-799ea88af195', 'Career', 'Adult', 'உங்கள் தொழில் வாழ்க்கையில் நீங்கள் அடைந்த மிகப்பெரிய சாதனை அல்லது பெருமிதம் எது?', 'What was the proudest achievement in your professional life?', 13, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('fc261bb4-7f16-48cc-a55a-007b9292e938', 'Challenges and achievements', 'Milestones', 'உங்கள் வாழ்வில் நீங்கள் எதிர்கொண்ட கடினமான சவால் என்ன? அதை எவ்வாறு வென்றீர்கள்?', 'What was the toughest challenge you faced, and how did you overcome it?', 20, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('41d019f3-43d5-40fc-8018-8b6fe920765d', 'Advice for future generations', 'Wisdom', 'உங்கள் அடுத்த தலைமுறை பேரக்குழந்தைகளுக்கு நீங்கள் கூற விரும்பும் பொன்னான அறிவுரை என்ன?', 'What golden advice and wisdom would you like to give to your grandchildren and future generations?', 21, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('e97fdeee-3f8e-45c2-ac1f-b25bca93b007', 'Childhood', 'Early Years', 'சிறுவயதில் நீங்கள் விரும்பி விளையாடிய பாரம்பரிய விளையாட்டுகள் என்ன?', 'What traditional games did you love playing as a child?', 3, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('0314d136-3cba-4d37-b95a-0fd076c9e2f1', 'Parents and siblings', 'Family', 'உங்கள் பெற்றோரைப் பற்றிய உங்களின் முதல் அல்லது மிக ஆழமான நினைவு எது?', 'What is your earliest or most profound memory of your parents?', 4, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('666f0aac-8fe5-470e-aeda-018c7d9c29aa', 'Parents and siblings', 'Family', 'உங்கள் உடன்பிறப்புகளுடனான உறவு எப்படி இருந்தது? அவர்கள் பற்றி கூறுங்கள்.', 'How was your relationship with your siblings? Tell us about them.', 5, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('0dbdb907-b4c8-42ed-a33d-b366cca3add2', 'School days', 'Education', 'உங்கள் பள்ளிப் பருவத்தைப் பற்றி சொல்லுங்கள். எப்படி பள்ளிக்குச் செல்வீர்கள்?', 'Tell us about your school days. How did you commute to school?', 6, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('ccad8692-7102-4efb-9a5d-33b5d5fec3d1', 'School days', 'Education', 'உங்கள் ஆசிரியர்களில் உங்களுக்கு மிகவும் பிடித்தவர் அல்லது உங்கள் வாழ்வில் மாற்றத்தை ஏற்படுத்தியவர் யார்?', 'Who was your favorite teacher or someone who made a deep impact on your life?', 7, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('f3cfd903-9cad-4d9b-8483-cf2a4b6b9313', 'Friends', 'Youth', 'உங்கள் பால்ய கால நண்பர்களில் யாரை இன்னும் நினைவில் வைத்திருக்கிறீர்கள்?', 'Which childhood friends do you still remember warmly?', 8, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('8a47f16f-86f8-454b-816b-35cd04a8c0bc', 'Education', 'Youth', 'நீங்கள் உயர்கல்வி அல்லது பிற பயிற்சிகள் பெற்ற அனுபவம் எப்படி இருந்தது?', 'How was your experience pursuing higher studies or vocational learning?', 9, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('7839c5fd-f7d9-400c-af7a-c4893bd57686', 'Marriage and family', 'Adult', 'உங்கள் திருமணம் எவ்வாறு நிச்சயமானது? அந்தத் திருமண நாள் எப்படி அமைந்தது?', 'How was your wedding arranged, and what was that wedding day like?', 11, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('40e4ca46-4854-49a9-8370-8d1f1da67040', 'Marriage and family', 'Adult', 'குடும்ப வாழ்க்கையின் தொடக்க கால நினைவுகள் பற்றி பகிர்ந்து கொள்ளுங்கள்.', 'Please share your memories from the early years of your married life.', 12, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('8a711621-5b56-4602-95e4-38a92373008c', 'Children', 'Family', 'உங்கள் குழந்தைகள் பிறந்த தருணத்தில் நீங்கள் உணர்ந்த உணர்வுகள் என்ன?', 'What emotions did you feel when your children were born?', 14, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('70e5db01-def3-462d-914f-e58402bcf20a', 'Children', 'Family', 'பிள்ளைகளை வளர்ப்பதில் நீங்கள் கடைப்பிடித்த முக்கிய நற்குணங்கள் என்ன?', 'What core values and ethics did you emphasize while raising children?', 15, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('9f58d193-2dae-44ee-99f8-ef98098f3f11', 'Festivals and traditions', 'Traditions', 'உங்கள் வீட்டில் பொங்கல், தீபாவளி போன்ற பண்டிகைகளை எப்படிக் கொண்டாடுவீர்கள்?', 'How did your family celebrate festivals like Pongal and Diwali?', 16, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('18a399dc-2fbd-4b84-9dbb-9a78ae6dbb4f', 'Festivals and traditions', 'Traditions', 'உங்கள் குடும்பத்தில் தலைமுறை தலைமுறையாகக் கடைப்பிடிக்கப்படும் தனித்துவமான வழக்கம் என்ன?', 'What is a cherished custom passed down through generations in your family?', 17, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.questions VALUES ('83dfda72-f077-4678-9f0c-0b49de890447', 'Friends', 'Youth', 'நண்பர்களுடன் சேர்ந்து செய்த மறக்க முடியாத நிகழ்வு அல்லது பயணம் ஏதாவது உண்டா?', 'Is there an unforgettable incident or trip you had with your friends?', 18, true, '2026-10-15 08:07:56.608+05:30', '2026-10-15 08:07:56.608+05:30') ON CONFLICT DO NOTHING;
