INSERT INTO public.transcripts VALUES ('91e9148e-e322-46ff-b063-10db2755b7b8', 'd9bb1850-fe91-4504-aea9-7cef98ff9ee8', 1, 'எனது சிறுவயது மிகவும் மகிழ்ச்சிகரமானதாக அமைந்திருந்தது. நண்பர்களுடன் விளையாடுவதும், குடும்பத்தினருடன் நேரம் செலவிடுவதும் எனக்கு மிகவும் விருப்பமானவையாக இருந்தன. அந்த இனிமையான நினைவுகள் இன்றும் என் உள்ளத்தில் நிலைத்திருக்கின்றன.', 'ta', 'speech_to_text', 'completed', '2026-10-15 16:39:27.279+05:30', NULL, NULL, 'My childhood was very happy. Playing with friends and spending time with family was my favorite. Those sweet memories still live on in my heart.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('342b53ca-3f41-4aeb-903e-71174b8fe4aa', '7697a5ce-8641-4b40-b72a-88d1f98e0317', 1, 'ஒலிப்பதிவில் பேச்சு எதுவும் கண்டறியப்படவில்லை (No speech detected in audio).', 'ta', 'speech_to_text', 'completed', '2026-10-22 20:04:43.069584+05:30', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('2f826dd2-6d61-4894-8e18-1b14f76e77b6', 'dc5959cd-8ae5-40f9-b357-f813f6851105', 1, 'பனிக்காலம்.', 'ta', 'speech_to_text', 'completed', '2026-10-23 18:14:27.934958+05:30', NULL, NULL, 'Winter.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('1e25dadc-8cf2-4661-ae75-f10999457635', 'ea77ca68-64de-435f-819a-6d0c6810a8c7', 4, 'பால்கார நண்பரான சுபத்ரா ஆசிரியை மற்றும் சரோஜினி ஆசிரியை ஆகியோர் தற்போது காலமானார்கள். அவர்களின் மகள் உமா, எங்கள் பள்ளிக்கூடத்தில் பயின்றவர்; தற்போது எங்கள் பள்ளி தலைமை ஆசிரியராகப் பணிபுரிகிறார். எனது உடன் பயின்ற தோழி காளிங்கராயம்பாளையத்தைச் சேர்ந்த ருக்மணி, தனது கல்வியை நிறைவு செய்து ஆசிரியர் பயிற்சி முடித்த பின், கோயம்புத்தூரில் ஆசிரியராகப் பணியாற்றி தற்போது ஓய்வு பெற்றுள்ளார். ஈஸ்வரி என்ற மகளை காளிங்கராயம்பாளையத்தில் திருமணம் செய்து கொடுத்துள்ளார்; அவர் தற்போது காளிங்கராயம்பாளையத்திலேயே வசித்து வருகிறார். இது பவானிக்கு அருகிலுள்ள பகுதியாகும்.', 'ta', 'speech_to_text', 'completed', '2026-10-15 17:58:04.392+05:30', NULL, NULL, 'Subhadra, a milkman''s friend, and Sarojini, a teacher, are now deceased. Their daughter, Uma, studied in our school and is currently working as our school principal. My classmate, Rukmani from Kalingarayampalayam, after completing her education and completing her teacher training, is now retired after working as a teacher in Coimbatore. Eshwari is married to Kalingarayampalayam and she is currently living in Kalingarayampalayam. This is the area near Bhavani.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('b513c73f-03ca-455a-b0cc-0791fc3e2027', '7697a5ce-8641-4b40-b72a-88d1f98e0317', 2, 'ஒலிப்பதிவில் பேச்சு எதுவும் கண்டறியப்படவில்லை (No speech detected in audio).', 'ta', 'speech_to_text', 'completed', '2026-10-22 20:05:41.632593+05:30', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
