INSERT INTO public.transcripts VALUES ('7b4a85c9-198e-420a-962f-bc11f7ac0e95', 'a7243b8e-cec7-4791-9331-f74184929575', 4, 'எங்கள் மாற்றத்தை அனைத்து ஆசிரியர்களும் சிறப்பாகக் கற்பித்தனர். சிறு வயதில், தொடக்கப் பள்ளியான சி.எஸ்.ஐ. பள்ளிக்கூடத்தில் ஐந்தாம் வகுப்பு வரை படித்தோம். அங்கு நான்காம் வகுப்பு ஆசிரியராகப் பணியாற்றிய ஞானசுந்தரம் என்பவர், எங்கள் அண்ணனின் திருமணத்திற்கு விடுப்பு எடுத்துக்கொண்டு, அடுத்த நாள் திருமணத்தை முடித்துக்கொண்டு புறப்படும்போது, ஒரு சதுரமான மரக்கட்டையைக் கையில் வைத்துக்கொண்டு, "ஏன் வரவில்லை?" என்று கேட்டதற்கு, "எங்கள் அண்ணனின் திருமணம் என்பதால் என்னால் வர இயலவில்லை. நீங்களும் திருமணத்திற்குச் சென்று வருகிறீர்களா?" என்று கூறியதற்கு, அவர் கையைத் திருப்பி எங்கள் கண்களிலேயே அடித்தார். அந்த நிகழ்வு இன்னும் எனக்கு நினைவிருக்கிறது. பின்னர், உயர்நிலைப் பள்ளியில் ஆசிரியர்கள் அனைவரும் சிறப்பாக நடந்து கொண்டனர்.', 'ta', 'speech_to_text', 'completed', '2026-10-15 18:04:00.394+05:30', NULL, NULL, 'All of our teachers taught our change very well. In our childhood, we studied up to the fifth standard in the CSI school, which was a primary school. Gnanasundaram, who worked as a fourth-grade teacher there, took leave for his brother''s wedding, and as he was leaving after finishing the wedding the next day, Holding a square log, "Why didn''t you come?To that, he replied, "I couldn''t come because it''s my brother''s wedding. Are you also going to the wedding?To what he had said, he turned his hand and struck our eyes. I still remember that incident. Then, the teachers at high school behaved well.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('d9a0b086-86c5-4c02-9a8a-7d9a8610d76d', '455452e0-66fc-4693-b912-413d01810aff', 2, 'நான் வளர்ந்த ஊர் பவானி ஆகும். அங்கு பழனிபுரம் கவுண்டர் தெருவில், மூன்றாவது வீதியில் நாங்கள் வசித்து வந்தோம். எங்கள் வீடு சாலையோர வீடாகும். அங்குதான் நாங்கள் அனைவரும் கல்வி பயின்றோம். எங்கள் வீட்டிற்கு இருபுறமும் ஆறு ஓடுகிறது. அங்கு சென்று அனைத்து வேலைகளையும் செய்வோம். எங்கள் தாயாருக்கு உதவியாக இருந்து அனைத்துப் பணிகளையும் செய்துவிட்டு, அங்கிருந்து நடந்து பள்ளிக்குச் செல்வோம். மதிய உணவுக்காக எங்கள் தாய் உணவினைத் தயாரித்து வைத்திருப்பார். அதனை உண்டுவிட்டு, மீண்டும் மதியம் 1:45-க்கு பள்ளிக்குச் செல்வோம். இது போதாதா? என்ன தேவைப்பட்டாலும் எங்கள் தாய் இருப்பார்.', 'ta', 'speech_to_text', 'completed', '2026-10-15 17:58:32.375+05:30', NULL, NULL, 'My hometown is Bawani. We lived in the third street, Gounder Street, Palani Pooram. Our house is a roadside house. That''s where we all studied. There is a river flowing on both sides of our house. We will go there and do all the work. We will help our mother and do all the work, and then walk to school from there. My mother prepares our lunch. We''ll have lunch on the run and will return to school at 1:45 pm. Is this not enough? Our mother will be there if we need anything.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('ad8341af-beee-4508-8009-de23a5176366', '7697a5ce-8641-4b40-b72a-88d1f98e0317', 5, 'எனது சிறுவயதுக்காலம் மிகவும் மகிழ்ச்சிகரமானதாக அமைந்திருந்தது. குடும்பத்தினருடன் நேரத்தைச் செலவிடுவதும், நண்பர்களுடன் இணைந்து விளையாடுவதுமாக எனது குழந்தைப்பருவம் அழகிய நினைவுகளால் நிறைந்திருந்தது.', 'ta', 'speech_to_text', 'completed', '2026-10-22 20:13:20.372269+05:30', NULL, NULL, 'My childhood was very joyful. Spending time with my family and playing together with friends, my childhood was filled with beautiful memories.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('187c023c-a7b3-4124-bbea-3d04617481d5', 'a7243b8e-cec7-4791-9331-f74184929575', 6, 'எங்கள் மாற்றத்தை அனைத்து ஆசிரியர்களும் சிறப்பாகக் கற்றுக் கொடுத்தனர். சிறு வயதில் ஆரம்பக் கல்வி சி.எஸ்.ஐ பள்ளிக்கூடத்தில் ஐந்தாம் வகுப்பு வரை படித்தோம். அங்கு நான்காம் வகுப்பு ஆசிரியராக இருந்த ஞானசுந்தரம் என்பவர், எங்கள் அண்ணன் திருமணத்திற்கு விடுப்பு எடுத்து, அடுத்த நாள் திருமணத்தை முடித்துவிட்டுச் சென்றபோது, ஒரு சதுரமான மரக்கட்டையைக் கையில் வைத்துக்கொண்டு, ''எங்கள் ஏழை'' என்று கேட்டதற்கு, ''எங்கள் அண்ணன் திருமணம், அதனால் என்னால் வர இயலவில்லை. நீயும் திருமணம் செய்துகொண்டு செல்வதாகவா?'' என்று கூறி, கையைத் திருப்பி எங்கள் கண்களைப் பார்த்து அடித்தார். அந்த நிகழ்வு இன்றும் எனக்கு நினைவிருக்கிறது. பின்னர், உயர்நிலைப் பள்ளியில் ஆசிரியர்கள் அனைவரும் மிகவும் நன்னடத்தையுடன் நடந்து கொண்டனர்.', 'ta', 'corrected', 'completed', '2026-10-15 18:04:42.611+05:30', '2026-10-15 18:04:42.611+05:30', NULL, 'All of our teachers taught us well. In my childhood, I studied up to the fifth standard in a CSI school. There, Gnanasundaram, who was a fourth-grade teacher, took leave for his brother''s wedding, and the next day, after finishing the wedding, when he was leaving, Holding a square piece of wood in his hand he said ''Our poor brother'' and to this the reply came ''He is married, so I cannot come. Are you also getting married?'' Saying that, he turned his hand, looked into our eyes and hit. I still remember that incident. Later, all of the teachers at the high school behaved very morally.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('543aa32d-5f1f-4a1c-aa92-a80e8dbd2dd7', '0d14479f-9061-46ab-981a-985a4fee1379', 2, 'நான் வளர்ந்த ஊர் மிகவும் அழகானதும் அமைதியானதுமாக இருந்தது. எங்கள் வீடு அன்பும் மகிழ்ச்சியும் நிறைந்தது. குடும்பத்தினருடன் நேரம் செலவிடுவதும் நண்பர்களுடன் விளையாடுவதும் எனக்கு மிகவும் விருப்பமானவையாக அமைந்தன.', 'ta', 'speech_to_text', 'completed', '2026-10-15 16:43:20.536+05:30', NULL, NULL, 'The town where I grew up was very beautiful and peaceful. Our home is filled with love and laughter. I''ve always enjoyed spending time with my family and friends.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('6256fda4-0ff1-47b8-b65e-97793933adb1', '0d14479f-9061-46ab-981a-985a4fee1379', 1, 'நான் வளர்ந்த ஊர் மிகவும் அழகாகவும் அமைதியாகவும் இருந்தது. எங்கள் வீடு அன்பும் மகிழ்ச்சியும் நிறைந்தது. குடும்பத்தினருடன் நேரம் செலவிடுவதும் நண்பர்களுடன் விளையாடுவதும் எனக்கு மிகவும் விருப்பமானவையாகும்.', 'ta', 'speech_to_text', 'completed', '2026-10-15 16:42:25.368+05:30', NULL, NULL, 'The place where I grew up was very beautiful and peaceful. Our home is filled with love and laughter. I like spending time with family and playing with my friends.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('8b3daf2d-e028-41c4-93f4-8a221f39ba3f', '0d14479f-9061-46ab-981a-985a4fee1379', 4, 'நான் வளர்ந்த ஊர் மிகவும் அழகானதும் அமைதியானதும் ஆகும். எங்கள் வீடு அன்பும் மகிழ்ச்சியும் நிறைந்தது. குடும்பத்தினருடன் நேரம் செலவிடுவதும் நண்பர்களுடன் விளையாடுவதும் எனக்கு மிகவும் விருப்பமானவையாக இருந்தன.', 'ta', 'speech_to_text', 'completed', '2026-10-15 16:43:33.381+05:30', NULL, NULL, 'The place where I grew up is very beautiful and peaceful. Our home is filled with love and laughter. I enjoyed spending time with family and playing with my friends.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('01715988-6a62-4e7d-8ae6-f997e0153acf', '7697a5ce-8641-4b40-b72a-88d1f98e0317', 6, 'எனது சிறுவயதுக்காலம் மிகவும் மகிழ்ச்சிகரமானதாக அமைந்திருந்தது. குடும்பத்தினருடன் நேரத்தைச் செலவிடுவதும், நண்பர்களுடன் இணைந்து விளையாடுவதுமாக எனது குழந்தைப்பருவம் அழகிய நினைவுகளால் நிறைந்திருந்தது.', 'ta', 'corrected', 'completed', '2026-10-22 20:34:30.186202+05:30', '2026-10-22 20:34:30.186+05:30', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('6ac3a68d-6907-4890-87d9-bfe19c08e081', 'ea77ca68-64de-435f-819a-6d0c6810a8c7', 6, 'பால்கார நண்பரான சுபத்ரா ஆசிரியை தற்போது காலமானார். சரோஜினி ஆசிரியை காலமானார். அவர்களது மகள் உமா, எங்கள் பள்ளிக்கூடத்தில் பயின்றார்; தற்போது எங்கள் பள்ளியின் தலைமை ஆசிரியராக உள்ளார். மேலும், என்னுடன் பயின்ற தோழி ருக்மணி காளிங்கராயம்பாளையத்தைச் சேர்ந்தவர். அவர் தனது கல்வியையும் ஆசிரியர் பயிற்சியையும் முடித்துவிட்டு, கோயம்புத்தூரில் ஆசிரியராகப் பணியாற்றி தற்போது ஓய்வு பெற்றுள்ளார். ஈஸ்வரி என்ற மகளை காளிங்கராயம்பாளையத்தில் திருமணம் செய்து கொடுத்துள்ளார்; அவர் தற்போது காளிங்கராயம்பாளையத்திலேயே வசிக்கிறார். இது பவானிக்கு அருகிலுள்ள காளிங்கராயம்பாளையமாகும்.', 'ta', 'corrected', 'completed', '2026-10-15 18:04:28.308+05:30', '2026-10-15 18:04:28.307+05:30', NULL, 'Teacher Subhadra, a milkman''s friend, has now passed away. Sarojini Shastri, the teacher, has passed away. Their daughter, Uma, studied in our school and is currently the headmistress of our school. Also, my friend Rukmani, who studied with me, is from Kalingarayampalayam. He completed his education and teacher training and is now retired, working as a teacher in Coimbatore. Eshwari is married to Kalingarayampalayam and she now lives in Kalingarayampalayam. It is near Bhavani, in Kalingarayampalayam.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('2cc298fc-878d-42d5-b526-46c66371d56f', '0d14479f-9061-46ab-981a-985a4fee1379', 9, 'நான் வளர்ந்த ஊர் மிகவும் அழகானதும் அமைதியானதுமாக இருந்தது. எங்கள் வீடு அன்பும் மகிழ்ச்சியும் நிறைந்தது. குடும்பத்தினருடன் நேரம் செலவிடுவதும், நண்பர்களுடன் விளையாடுவதும் எனக்கு மிகவும் பிடித்தமானவையாக இருந்தன.', 'ta', 'corrected', 'completed', '2026-10-15 17:24:35.867+05:30', '2026-10-15 17:24:35.866+05:30', NULL, 'The town where I grew up was very beautiful and peaceful. Our home is filled with love and laughter. I enjoyed spending time with family and playing with my friends.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('7af4263e-72ea-4e26-b94d-f97f97359a6b', '5b0bdf49-a295-4282-8a59-c5894a7f1718', 3, 'எனது குழந்தைப் பருவம் புருஷாமலத்திலிருந்து தொடங்கியது. புருஷாமலத்திலிருந்து பவானிக்கு வந்தோம். சி.எஸ்.ஐ பள்ளிக்கூடத்தில் படித்தோம். அங்கு ஒன்று முதல் ஐந்து வரையிலான வகுப்புகளைப் படித்தோம். பின்னர் பெண்கள் உயர்நிலைப் பள்ளியில் படித்தோம். அங்கு சிறுவர், சிறுமியர் இருபாலரும் பயிலும் இணைக்கல்வி முறையில் கல்வி பயின்றோம்.
INSERT INTO public.transcripts VALUES ('2d67e995-9ffc-4da7-9e8b-507d0590751e', '0d14479f-9061-46ab-981a-985a4fee1379', 5, 'நான் வளர்ந்த ஊர் மிகவும் அழகானதும் அமைதியானதும் ஆகும். எங்கள் வீடு அன்பும் மகிழ்ச்சியும் நிறைந்தது. குடும்பத்தினருடன் நேரம் செலவிடுவதும் நண்பர்களுடன் விளையாடுவதும் எனக்கு மிகவும் விருப்பமானவையாக இருந்தன.', 'ta', 'corrected', 'completed', '2026-10-15 17:08:48.139+05:30', '2026-10-15 17:08:48.139+05:30', NULL, 'The place where I grew up is very beautiful and peaceful. Our home is filled with love and laughter. I enjoyed spending time with family and playing with my friends.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('b7848f3e-2edb-4e24-9b9c-05de3e3afd0a', '0d14479f-9061-46ab-981a-985a4fee1379', 7, 'நான் வளர்ந்த ஊர் மிகவும் அழகானதும் அமைதியானதுமாக இருந்தது. எங்கள் இல்லம் அன்பும் மகிழ்ச்சியும் நிறைந்திருந்தது. குடும்பத்தினருடன் நேரம் செலவிடுவதும் நண்பர்களுடன் விளையாடுவதும் எனக்கு மிகவும் விருப்பமானவையாக இருந்தன.', 'ta', 'corrected', 'completed', '2026-10-15 17:08:57.408+05:30', '2026-10-15 17:08:57.408+05:30', NULL, 'The town where I grew up was very beautiful and peaceful. Our home was filled with love and joy. I enjoyed spending time with family and playing with my friends.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('047a8c80-78a1-4511-a442-4276518eea35', 'ea77ca68-64de-435f-819a-6d0c6810a8c7', 5, 'பால்கார நண்பரான சுபத்ரா ஆசிரியை மற்றும் சரோஜினி ஆசிரியை ஆகியோர் தற்போது காலமானார்கள். அவர்களின் மகள் உமா, எங்கள் பள்ளிக்கூடத்தில் பயின்றார்; தற்போது எங்கள் பள்ளியில் தலைமை ஆசிரியராகப் பணிபுரிகிறார். எனது உடன் பயின்ற தோழி காளிங்கராயம்பாளையத்தைச் சேர்ந்த ருக்மணி, தனது கல்வியையும் ஆசிரியர் பயிற்சிப் படிப்பையும் முடித்துவிட்டு கோயம்புத்தூரில் ஆசிரியராகப் பணியாற்றி தற்போது ஓய்வு பெற்றுள்ளார். அவர் தனது ஈஸ்வரி என்ற மகளைக் காளிங்கராயம்பாளையத்தில் திருமணம் செய்து கொடுத்துள்ளார்; அவர் காளிங்கராயம்பாளையத்திலேயே வசிக்கிறார். இது பவானிக்கு அருகிலுள்ள காளிங்கராயம்பாளையம் ஆகும்.', 'ta', 'corrected', 'completed', '2026-10-15 18:04:21.251+05:30', '2026-10-15 18:04:21.25+05:30', NULL, 'Subhadra, a milkman''s friend, and Sarojini, a teacher, have now passed away. Their daughter, Uma, studied in our school and is now the headmistress of our school. My classmate, Rukmani from Kalingarayampalayam, has completed her education and teacher training and is now retired after working as a teacher in Coimbatore. He has married off his daughter, Easwari, to Kalingarayampalayam; she now lives in Kalingarayampalayam. It is near Bhavani, in the Kalingarayampalayam village.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('19edddae-86d4-4c18-b7be-8b782fa5808b', 'd9bb1850-fe91-4504-aea9-7cef98ff9ee8', 3, 'எனது சிறுவயது மிகுந்த மகிழ்ச்சியுடையதாக இருந்தது. நண்பர்களுடன் விளையாடுவதும், குடும்பத்தினருடன் காலத்தைக் கழிப்பதும் எனக்கு மிகவும் விருப்பமானவையாக இருந்தன. அந்த இனிய நினைவுகள் இன்றும் எனது உள்ளத்தில் நிலைத்திருக்கின்றன.', 'ta', 'corrected', 'completed', '2026-10-15 16:52:50.691+05:30', '2026-10-15 16:52:50.69+05:30', NULL, 'My childhood was very joyful. Playing with friends and spending time with family were the things I enjoyed the most. Those sweet memories still remain in my heart.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('50052c97-f755-4e1f-9b52-cb2d69067309', '2679b61d-09ea-4e76-9ebb-1dd76b02b4f4', 2, 'பாரம்பரிய விளையாட்டுகள் எதையும் விளையாடுவதில்லை. நாங்கள் எங்கும் செல்வதில்லை; வீட்டிலேயே தங்கி அம்மாவுக்கு உதவுவோம். வீட்டிலும் நானும் எனது தங்கையும் இருவருமே அப்பாவுக்கும் அம்மாவுக்கும் உதவியாக இருப்போம். வீட்டை விட்டு வெளியெங்கும் செல்வதில்லை.
INSERT INTO public.transcripts VALUES ('6a047c8c-08b1-493e-87c0-512202f04b10', '0d14479f-9061-46ab-981a-985a4fee1379', 6, 'நான் வளர்ந்த ஊர் மிகவும் அழகானதும் அமைதியானதும் ஆகும். எங்கள் வீடு அன்பும் மகிழ்ச்சியும் நிறைந்ததாக இருந்தது. குடும்பத்தினருடன் நேரம் செலவிடுவதும் நண்பர்களுடன் விளையாடுவதும் எனக்கு மிகவும் விருப்பமானவையாக இருந்தன.', 'ta', 'corrected', 'completed', '2026-10-15 17:08:53.293+05:30', '2026-10-15 17:08:53.293+05:30', NULL, 'The place where I grew up is very beautiful and peaceful. Our home was filled with love and laughter. I enjoyed spending time with family and playing with my friends.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('c0023f8f-7077-4f8d-ab9e-db133944b211', '50886abd-184f-4dcf-94d9-e5241d2ad7f3', 2, 'எங்கள் பெற்றோர் எங்கள் மீது மிகுந்த அன்பு கொண்டிருந்தனர். எங்களை எங்கும் அனுப்பவோ, பிறர் வீடுகளுக்கு அனுப்பவோ அவர்கள் விரும்பவில்லை. எங்கள் தேவைகளை அவர்களே நிறைவேற்றித் தருவார்கள். எங்கள் பெற்றோர் இன்றி எங்களால் வாழ முடியாது. நாங்கள் எங்கு சென்றாலும், காலைச் சென்றுவிட்டு மாலையில் திரும்பி வருவார்கள். அது என் தந்தைக்கு என் மீதுள்ள மிகுந்த அன்பைக் காட்டுகிறது.', 'ta', 'corrected', 'completed', '2026-10-15 18:05:05.559+05:30', '2026-10-15 18:05:05.559+05:30', NULL, 'Our parents loved us very much. They don''t want us to be sent anywhere or to other houses. They will meet our needs. We cannot live without our parents. Wherever we went, they would leave in the morning and come back in the evening. That shows how much my father loves me.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('c7e6d588-00e7-4894-80a3-84aed733116c', '0d14479f-9061-46ab-981a-985a4fee1379', 8, 'நான் வளர்ந்த ஊர் மிகவும் அழகானதும் அமைதியானதுமாக இருந்தது. எங்கள் வீடு அன்பும் மகிழ்ச்சியும் நிறைந்தது. குடும்பத்தினருடன் நேரம் செலவிடுவதும், நண்பர்களுடன் விளையாடுவதும் எனக்கு மிகவும் விருப்பமானவையாக இருந்தன.', 'ta', 'corrected', 'completed', '2026-10-15 17:09:27.342+05:30', '2026-10-15 17:09:27.342+05:30', NULL, 'The town where I grew up was very beautiful and peaceful. Our home is filled with love and laughter. I was very fond of spending time with family and playing with friends.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('24513c18-28cd-48ce-9175-dcd81d01c3d1', 'e8b050ff-3024-4380-83d5-5fc62b414757', 1, 'பள்ளிக்கூடம் சென்று நடந்து வந்தோம். காலை வேளையில் சென்றுவிட்டு, மதிய உணவு அருந்துவதற்காக வீடு திரும்புவோம். வீட்டிற்கு வந்து உணவு அருந்திய பின்பு, மீண்டும் மதியம் சென்றால் மாலை வேளையில் வீடு திரும்புவோம். வீட்டிற்கு வந்ததும், எங்கள் அன்னையருக்கு நீர் தேவை என்று கிணற்றிலிருந்து நீரை இறைத்து வந்து ஊற்றி வைப்போம். பின்னர் இருவரும் அமர்ந்து படிப்போம். எங்கள் வீட்டில் மின்சார வசதி இல்லை. எனவே, சீமை விளக்கு வெளிச்சத்திலேயே நாங்கள் படித்தோம்.', 'ta', 'speech_to_text', 'completed', '2026-10-15 17:48:56.925+05:30', NULL, NULL, 'We went to school and walked. We will leave in the morning and return home for lunch. After coming home and having food, if we go for lunch again, we will return home in the evening. As soon as we arrive home, we will draw water from the well and pour it for our mother. Then, both of us will sit and study. We don''t have electricity in our house. So, we studied with the light of a lamp.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('ba8db3a1-39d2-405f-97af-109150234cb8', '50886abd-184f-4dcf-94d9-e5241d2ad7f3', 1, 'எங்கள் பெற்றோர் எங்கள் மீது மிகுந்த அன்பு கொண்டிருந்தனர். எங்களை எங்கும் அனுப்ப மாட்டார்கள்; பிறர் இல்லங்களுக்கும் அனுப்ப மாட்டார்கள். எங்கள் தேவைகளை அவர்களே நிறைவேற்றித் தருவார்கள். எங்கள் பெற்றோர் இல்லாமல் எங்களால் வாழ முடியாது. நாங்கள் எங்கு சென்றாலும், காலைச் சென்று மாலை திரும்பும் வரை உடனிருப்பார்கள். அது என் மீது என் தந்தைக்கு இருந்த மிகுந்த அன்பைக் காட்டுகிறது.', 'ta', 'speech_to_text', 'completed', '2026-10-15 17:47:32.575+05:30', NULL, NULL, 'Our parents loved us very much. They will not send us everywhere; they will not send us to other people''s houses. They will meet our needs. We cannot live without our parents. Wherever we went, they were there from morning till evening. It shows how much my father loved me.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('ac129326-58da-43b9-b67b-2f24f0baa439', 'a7243b8e-cec7-4791-9331-f74184929575', 3, 'எங்கள் மாற்றத்தை அனைத்து ஆசிரியர்களும் சிறப்பாகக் கற்பித்தார்கள். சிறுவயதில் தொடக்கப்பள்ளியான சி.எஸ்.ஐ. பள்ளிக்கூடத்தில் ஐந்தாம் வகுப்பு வரை படித்தோம். அங்கு நான்காம் வகுப்பு ஆசிரியராகப் பணியாற்றிய ஞானசுந்தரம் என்பவர், எங்கள் அண்ணனின் திருமணத்திற்கு விடுப்பு எடுத்துச் சென்றிருந்தார். அடுத்த நாள் திருமணத்தை முடித்துவிட்டு அவர் திரும்பும் போது, ஒரு சதுரமான மரக்கட்டையைக் கையில் ஏந்தியபடி, "உங்கள் ஏழை" என்று என்னைக் குறிப்பிட்டதற்கு, "எங்கள் அண்ணனின் திருமணம் என்பதால் என்னால் வர இயலவில்லை. நீங்களும் திருமணம் செய்துகொண்டு செல்கிறீர்களா?" என்று கூறி, என் தலையில் அடித்துவிட்டார். அந்த நிகழ்வு இன்னும் எனக்கு நினைவிருக்கிறது. பின்னர் உயர்நிலைப் பள்ளியில் ஆசிரியர்கள் அனைவரும் மிகவும் சிறப்பாகப் பழகினார்கள்.', 'ta', 'speech_to_text', 'completed', '2026-10-15 17:58:14.56+05:30', NULL, NULL, 'All of our teachers taught our change very well. In my childhood, I studied up to the fifth grade in the CSI school, which was a primary school. Gnanasundaram, who worked as a fourth-grade teacher there, had taken leave for his brother''s wedding. The next day, after the wedding was done, as he was returning, holding a square piece of wood in his hand, he mentioned to me, "Your poor man." "I couldn''t come because it was my brother''s wedding. Are you also getting married and leaving?" Saying that, he hit me on the head. I still remember that incident. Then, in high school, all of the teachers got along very well.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('bd2fd6a8-f91d-412f-a2ed-67d0646fd3f9', '5b0bdf49-a295-4282-8a59-c5894a7f1718', 2, 'எனது குழந்தைப்பருவம் புருஷாமலத்திலிருந்து தொடங்கியது. புருஷாமலத்திலிருந்து பவானிக்கு வந்தோம். சி.எஸ்.ஐ பள்ளிக்கூடத்தில் படித்தோம். அங்கு ஒன்று, இரண்டு, மூன்று, நான்கு, ஐந்து எனப் படித்தோம். பின்னர் பெண்கள் உயர்நிலைப் பள்ளியில் படித்தோம். அங்கு சிறுவர், சிறுமியர் இணைந்து பயிலும் இணைக்கல்வி முறையில் படித்தோம்.
INSERT INTO public.transcripts VALUES ('7cf5ec91-be51-406d-9b1a-614d81ed4629', 'ea77ca68-64de-435f-819a-6d0c6810a8c7', 7, 'பால்கார நண்பரான சுபத்ரா ஆசிரியை மற்றும் சரோஜினி ஆசிரியை ஆகியோர் தற்போது காலமாயினர். அவர்கள் மகள் உமா, எங்கள் பள்ளிக்கூடத்தில் பயின்றார்; தற்போது எங்கள் பள்ளியில் தலைமை ஆசிரியராக இருப்பவர் அவர்தான். மேலும், என்னுடன் பயின்ற தோழி ருக்மணி, காளிங்கராயம்பாளையத்தைச் சேர்ந்தவர். அவர் தனது கல்வியை முடித்து ஆசிரியர் பயிற்சிப் படிப்பை முடித்த பிறகு, கோயம்புத்தூரில் ஆசிரியராகப் பணியாற்றி தற்போது ஓய்வு பெற்றுள்ளார். ஈஸ்வரி என்ற ஒரு மகளை காளிங்கராயம்பாளையத்தில் திருமணம் செய்து கொடுத்து, அவர் அங்கேயே வசித்து வருகிறார். இது பவானிக்கு அருகிலேயே அமைந்துள்ள ஊராகும்.', 'ta', 'corrected', 'completed', '2026-10-15 18:04:32.108+05:30', '2026-10-15 18:04:32.108+05:30', NULL, 'Subhadra, a milkman friend, and Sarojini, a teacher, are now deceased. Their daughter, Uma, studied in our school; she is currently the headmistress of our school. Furthermore, my friend Rukmani, who studied with me, is from Kalingarayampalayam. He completed his education, completed his teacher training, and is now retired, working as a teacher in Coimbatore. He is married to a girl named Eshwari in Kalingarayampalayam and lives there. It is a town located close to Bhavani.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('43d46410-7abf-4e5a-85b4-7848c64888af', '0d14479f-9061-46ab-981a-985a4fee1379', 3, 'நான் வளர்ந்த ஊர் மிகவும் அழகானதும் அமைதியானதுமாக இருந்தது. எங்கள் வீடு அன்பும் மகிழ்ச்சியும் நிறைந்தது. குடும்பத்தினருடன் நேரம் செலவிடுவதும் நண்பர்களுடன் விளையாடுவதும் எனக்கு மிகவும் விருப்பமானவையாக அமைந்தன.', 'ta', 'speech_to_text', 'completed', '2026-10-15 16:43:23.283+05:30', NULL, NULL, 'The town where I grew up was very beautiful and peaceful. Our home is filled with love and laughter. I''ve just discovered that I love to spend time with my family and friends.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('fb7ce3d8-60ea-45f2-a7a9-b7dbbe81452f', 'd9bb1850-fe91-4504-aea9-7cef98ff9ee8', 2, 'எனது சிறுவயது மிகவும் மகிழ்ச்சிகரமாக அமைந்திருந்தது. நண்பர்களுடன் விளையாடுவதும், குடும்பத்தினருடன் நேரம் செலவிடுவதும் எனக்கு மிகவும் விருப்பமானவையாக இருந்தன. அந்த இனிய நினைவுகள் இன்றும் எனது மனதில் நிலைத்திருக்கின்றன.', 'ta', 'speech_to_text', 'completed', '2026-10-15 16:52:39.947+05:30', NULL, NULL, 'My childhood was very happy. Playing with friends and spending time with family was my favorite. Those sweet memories still live on in my heart.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('f5e87071-e545-4472-b3e3-9d654e074741', 'a7243b8e-cec7-4791-9331-f74184929575', 5, 'எங்கள் மாற்றத்தை அனைத்து ஆசிரியர்களும் சிறப்பாகக் கற்றுக் கொடுத்தனர். சிறு வயதில் எலிமெண்டரி சி.எஸ்.ஐ பள்ளிக்கூடத்தில் ஐந்தாம் வகுப்பு வரை படித்தோம். அங்கு ஞானசுந்தரம் என்ற நான்காம் வகுப்பு ஆசிரியர் இருந்தார். எங்கள் அண்ணனின் திருமணத்திற்கு அவர் விடுப்பு எடுத்து, அடுத்த நாள் திருமணம் முடிந்து நாங்கள் புறப்பட்டபோது, அவர் ஒரு சதுரமான மரக்கட்டையை கையில் வைத்துக்கொண்டு, "ஏழை" என்று எங்களைக் குறிப்பிட்டதற்கு, "எங்கள் அண்ணனின் திருமணம் என்பதால் எங்களால் வர இயலவில்லை. நீங்களும் திருமணம் முடிந்து செல்கிறீர்களா?" என்று கூறி, என் கண்களைத் திருப்பிப் பார்த்து அடித்தார். அந்த நிகழ்வு இன்னும் எனக்கு நினைவிருக்கிறது. பின்னர் உயர்நிலைப் பள்ளியில் ஆசிரியர்கள் அனைவரும் சிறப்பாக நடந்து கொண்டனர்.', 'ta', 'corrected', 'completed', '2026-10-15 18:04:34.891+05:30', NULL, NULL, 'All of our teachers taught us well. In my childhood, I studied up to the fifth grade in an elementary CSI school. There was a fourth-grade teacher named Gnanasundaram. For my brother''s wedding, he took leave, and the next day after the wedding was over, as we were leaving, he held a square piece of wood in his hand, “We cannot come because we are poor and it is my brother’s wedding. Are you also getting married and leaving?" Saying that, he turned his eyes and hit. I still remember that incident. Then, all of the teachers in high school behaved well.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('a6e456a1-7bde-4dcd-85b1-6c014f8ad33e', 'e8b050ff-3024-4380-83d5-5fc62b414757', 2, 'பள்ளிக்கூடம் செல்வதற்கு நாங்கள் நடந்தே செல்வோம். காலை வேளையில் சென்றுவிட்டு, மதிய உணவுக்காக வீடு திரும்புவோம். வீட்டிற்கு வந்து உணவருந்திவிட்டு, மீண்டும் மதியம் சென்றால், மாலை வீடு திரும்புவோம். வீட்டிற்கு வந்ததும், எங்கள் தாயாருக்கு நீர் தேவை என கிணற்றிலிருந்து நீரைச் சுமந்து வந்து ஊற்றி வைப்போம். பின்னர் இருவரும் அமர்ந்து படிப்போம். எங்கள் வீட்டில் மின்சார வசதி இல்லை. எனவே, நாங்கள் சீமை விளக்கின் ஒளியிலேயே படித்தோம்.', 'ta', 'corrected', 'completed', '2026-10-15 18:04:49.357+05:30', '2026-10-15 18:04:49.357+05:30', NULL, 'We will walk to school. We''ll leave in the morning and return home for lunch. After having our meal at home, we will return home in the evening. After coming home, we will bring water from the well and pour it for our mother, who needs water. Then both of us will sit and study. We don''t have electricity in our house. So, we studied with the light of a chandelier.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('f585c465-802e-4902-bf61-64ecf086d521', '455452e0-66fc-4693-b912-413d01810aff', 3, 'நான் வளர்ந்த ஊர் பவானி. பவானி பழனிபுரம் கவுண்டர் தெருவில், மூன்றாவது வீதியில் நாங்கள் வசித்தோம். எங்களின் வீடு சாலையோர வீடாகும். அங்குதான் நாங்கள் அனைவரும் கல்வி பயின்றோம். எங்கள் வீட்டிற்கு இருபுறமும் ஆறு ஓடுகிறது; வீட்டைச் சென்று அனைத்து வேலைகளையும் செய்தோம். எங்கள் தாய்க்கு உதவியாக அனைத்துப் பணிகளையும் செய்துவிட்டு, அங்கிருந்து நடந்தே பள்ளிக்குச் செல்வோம். பின்னர் மதிய உணவிற்காக எங்கள் தாய் உணவு தயாரித்து வைத்திருப்பார். அதனை உண்டுவிட்டு, மீண்டும் பிற்பகல் 1:45-க்கு பள்ளிக்குச் செல்வோம். இது போதுமா? வேறு ஏதேனும் வேண்டுமா? எங்கள் தாய் இருப்பார்.', 'ta', 'corrected', 'completed', '2026-10-15 18:05:17.407+05:30', '2026-10-15 18:05:17.407+05:30', NULL, 'My hometown is Bawani. We lived in the third street, Gounder street, Pavani Palani. Our house is a roadside house. That''s where we all studied. There is a river on both sides of our house; we went to the house and did all the work. After helping my mother with all her work, we walked to school. Then, for lunch, our mother will prepare food. After that, we will go back to school at 1:45 pm. Will this be enough? Is there anything else you need? Our mother will be there.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('e9ea8354-585d-4f14-a8d1-bc7acb9bc8b0', '2679b61d-09ea-4e76-9ebb-1dd76b02b4f4', 1, 'பாரம்பரிய விளையாட்டுகள் எதுவும் எங்களுக்குத் தெரியாது. நாங்கள் எங்கும் வெளியே செல்வதில்லை; வீட்டிற்குள்ளேயே இருப்போம். எங்கள் தாய்க்கு உதவுவோம். நானும் எனது தங்கையும் வீட்டில் எங்கள் தந்தைக்கும் தாய்க்கும் உதவியாக இருப்போம். வீட்டை விட்டு வெளியே எங்கும் செல்வதில்லை.
INSERT INTO public.transcripts VALUES ('847e2cd1-77dd-4e35-9abc-76ed8d268aba', 'f1ee6da5-2e9a-48c5-b6f0-ea0153448d0d', 2, 'எனக்கு இரண்டு அண்ணன்கள் உள்ளனர்; அவர்கள் இருவரும் எனக்கு மூத்தவர்கள். அவர்கள் அனைவரும் கல்வி பயின்று வேலைக்குச் சென்றனர். மூத்த அண்ணன் நில அடமான வங்கியில் செயலாளராகப் பணியாற்றினார். இளைய அண்ணன் உயர்நிலைப் பள்ளியில் குமாஸ்தாவாகப் பணியாற்றினார். நானும் எனது தங்கையும் ஒன்றாகப் பள்ளிக்கூடம் சென்றோம்; ஒன்றாகவே வீடு திரும்பினோம். நான் கல்வி கற்றேன், ஆனால் அவளுக்குக் கல்வி கற்பதற்கு இடமளிக்கப்படவில்லை. எனவே, அவள் வேலைக்குச் செல்லவில்லை. எனது தங்கையார் சேலம் நகரில் வசிக்கிறார்.', 'ta', 'corrected', 'completed', '2026-10-15 18:04:54.275+05:30', '2026-10-15 18:04:54.275+05:30', NULL, 'I have two older brothers. They all went to work after getting their education. The elder brother worked as a secretary in a land mortgage bank. The younger brother worked as a clerk in a high school. My sister and I went to school together; we returned home together. I was educated, but she was not given the opportunity to be educated. So, she didn''t go to work. My sister lives in Salem city.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('c731c997-ce7a-4b48-b055-a2600cda518d', '455452e0-66fc-4693-b912-413d01810aff', 4, 'நான் வளர்ந்த ஊர் பவானி, பவானி பழனிபுரம் கவுண்டர் தெருவில். மூன்றாவது வீதியில் நாங்கள் வசித்தோம். எங்கள் வீடு சாலையோர வீடாகும். அங்குதான் நாங்கள் அனைவரும் கல்வி பயின்றோம். எங்கள் வீட்டிற்கு இருபுறமும் ஆறு ஓடுகிறது. வீட்டிற்குச் சென்று அனைத்து வேலைகளையும் செய்வோம். எங்கள் தாய்க்கு உதவியாக அனைத்து வேலைகளையும் செய்துவிட்டு, அங்கிருந்து நடந்து பள்ளிக்குச் செல்வோம். மதிய உணவிற்கு எங்கள் தாய் தயாரித்து வைத்திருப்பார். அதனை உண்டுவிட்டு, மீண்டும் மதியம் 1:45-க்கு பள்ளிக்குச் செல்வோம். இது போதாதா? என்ன தேவைப்பட்டாலும் தாய் இருக்கிறார்.', 'ta', 'corrected', 'completed', '2026-10-16 08:20:54.453+05:30', '2026-10-16 08:20:54.452+05:30', NULL, 'My hometown is Bhavani, Bhavani Palani Pooram, Gownder Street. We lived on the third street. Our house is a roadside house. That''s where we all studied. There is a river flowing on both sides of our house. We will go home and do all the work. We will help our mother and finish all the chores before walking to school. For lunch, our mother will prepare. We''ll have lunch on the run and will return to school at 1:45 pm. Is this not enough? A mother is always there to support you in whatever you do.') ON CONFLICT DO NOTHING;
INSERT INTO public.transcripts VALUES ('2038357a-e686-4536-88f5-4a38bfd4fdd4', 'f1ee6da5-2e9a-48c5-b6f0-ea0153448d0d', 1, 'எங்களுக்கு இரண்டு சகோதரர்கள் உள்ளனர். அவர்கள் இருவரும் எனக்கு மூத்தவர்கள். அவர்கள் அனைவரும் கல்வி பயின்று வேலைக்குச் சென்றனர். மூத்த சகோதரர் நில அடமான வங்கியில் செயலாளராகப் பணியாற்றினார். இளைய சகோதரர் உயர்நிலைப் பள்ளியில் குமாஸ்தாவாக இருந்தார். நானும் எனது தங்கையும் ஒன்றாகப் பள்ளிக்கூடம் சென்றோம்; ஒன்றாகவே வீடு திரும்பினோம். நான் கல்வி கற்றேன், ஆனால் அவளுக்குக் கல்வி கற்க வாய்ப்பு கிடைக்கவில்லை. அவள் வேலைக்குச் செல்லவில்லை. எனது தங்கையார் தற்போது சேலத்தில் வசிக்கிறார்.', 'ta', 'speech_to_text', 'completed', '2026-10-15 17:48:16.958+05:30', NULL, NULL, 'We have two brothers. They are both older than me. All of them are educated and have gone to work. The elder brother worked as a secretary in a land mortgage bank. The younger brother was a clerk in a high school. My sister and I went to school together; we returned home together. I was educated, but she had no chance to get an education. She didn''t go to work. My sister is currently residing in Salem.') ON CONFLICT DO NOTHING;
INSERT INTO public.event_sources VALUES ('5bd3f341-bc19-462a-9b50-5ffdc81c3449', '7697a5ce-8641-4b40-b72a-88d1f98e0317', '01715988-6a62-4e7d-8ae6-f997e0153acf', 'எனது சிறுவயதுக்காலம் மிகவும் மகிழ்ச்சிகரமானதாக அமைந்திருந்தது. குடும்பத்தினருடன் நேரத்தைச் செலவிடுவதும், நண்பர்களுடன் இணைந்து விளையாடுவதுமாக எனது குழந்தைப்பருவம் அழகிய நினைவுகளால் நிறைந்திருந்தது.') ON CONFLICT DO NOTHING;
INSERT INTO public.event_sources VALUES ('795dd2c8-dc3e-489b-8367-87dcdcc67b69', '5b0bdf49-a295-4282-8a59-c5894a7f1718', '7af4263e-72ea-4e26-b94d-f97f97359a6b', 'சொல்லு. பேசுங்க. என்னுடைய குழந்தை பருவம் நான் வந்து புருஷாமலத்திலிருந்து அப்படித்தானே? புருஷாமலத்திலிருந்து பவானி வந்தோம். சிஎஸ்ஐ பள்ளிக்கூடத்துல படிச்சோம். சிஎஸ்ஐ பள்ளிக்கூடத்துல ஒன்னு ரெண்டு மூணு நா') ON CONFLICT DO NOTHING;
