INSERT INTO public.event_sources VALUES ('1d7ea9f7-7f3d-4a61-980f-b825eb5792da', '2679b61d-09ea-4e76-9ebb-1dd76b02b4f4', '50052c97-f755-4e1f-9b52-cb2d69067309', 'பாரம்பரிய விளையாட்டு எல்லாம் இல்ல கண்ணு நாங்க எல்லாம் எங்கேயுமே போக மாட்டோம் வீட்டோட சரி எங்க அம்மாவுக்கு உதவி செய்வோம். வீட்ல நானும் எங்க தங்கச்சியும் ரெண்டு பேரும் வீட்ல இருந்து எங்க அப்பா எங்க அம்ம') ON CONFLICT DO NOTHING;
INSERT INTO public.event_sources VALUES ('551fa2f5-9a07-4f3c-b723-d208415ffca3', '2679b61d-09ea-4e76-9ebb-1dd76b02b4f4', '50052c97-f755-4e1f-9b52-cb2d69067309', 'பாரம்பரிய விளையாட்டு எல்லாம் இல்ல கண்ணு நாங்க எல்லாம் எங்கேயுமே போக மாட்டோம் வீட்டோட சரி எங்க அம்மாவுக்கு உதவி செய்வோம். வீட்ல நானும் எங்க தங்கச்சியும் ரெண்டு பேரும் வீட்ல இருந்து எங்க அப்பா எங்க அம்ம') ON CONFLICT DO NOTHING;
INSERT INTO public.event_sources VALUES ('748d4b7a-9f81-4fca-9d52-f50d88e17bc0', '50886abd-184f-4dcf-94d9-e5241d2ad7f3', 'c0023f8f-7077-4f8d-ab9e-db133944b211', 'எங்க அம்மா அப்பா வந்து எங்க மேல ரொம்ப பிரியம். எங்களை எங்கேயும் அனுப்ப மாட்டாங்க, யார் வீட்டுக்கும் அனுப்ப மாட்டாங்க. எங்க தேவைக்கு அவங்களே எல்லாம் செஞ்சு கொடுத்துருவாங்க. எங்க அம்மா அப்பா இல்லாம எங்க') ON CONFLICT DO NOTHING;
INSERT INTO public.event_sources VALUES ('b876fa60-b383-4dd0-9a5f-878877059666', 'f1ee6da5-2e9a-48c5-b6f0-ea0153448d0d', '847e2cd1-77dd-4e35-9abc-76ed8d268aba', 'எங்கள் உடன்பிறப்பு வந்து எனக்கு ரெண்டு அண்ணன். ரெண்டு அண்ணன், ரெண்டு அண்ணனு எனக்கு மூத்தவங்க. அவங்க எல்லாம் படிச்சு வேலைக்குத்தான் இருந்தாங்க. எங்க அண்ணன் வந்து நில அடமான பேங்க்ல செக்ரட்டரியா இருந்தாப') ON CONFLICT DO NOTHING;
