INSERT INTO public.event_sources VALUES ('a8c089cd-aa0c-49b6-a124-15edb60cc2ec', 'e8b050ff-3024-4380-83d5-5fc62b414757', 'a6e456a1-7bde-4dcd-85b1-6c014f8ad33e', 'பள்ளிக்கு நடந்து தான் போவோம். காலையில போயிட்டு மத்தியானம் சாப்பாட்டுக்கு வீட்டுக்கு வருவோம். வீட்டுக்கு வந்து சாப்பிட்டுட்டு மறுபடியும் மத்தியானம் போனோம்னா சாயங்காலம் வீட்டுக்கு வந்துருவோம். வீட்டுக்க') ON CONFLICT DO NOTHING;
