INSERT INTO public.event_sources VALUES ('fab0793b-efa4-4140-9c95-82a06c35b6ec', '2679b61d-09ea-4e76-9ebb-1dd76b02b4f4', '50052c97-f755-4e1f-9b52-cb2d69067309', 'பாரம்பரிய விளையாட்டு எல்லாம் இல்ல கண்ணு நாங்க எல்லாம் எங்கேயுமே போக மாட்டோம் வீட்டோட சரி எங்க அம்மாவுக்கு உதவி செய்வோம். வீட்ல நானும் எங்க தங்கச்சியும் ரெண்டு பேரும் வீட்ல இருந்து எங்க அப்பா எங்க அம்ம') ON CONFLICT DO NOTHING;
INSERT INTO public.event_sources VALUES ('a0c4df9a-e257-4286-8ce9-4049f00d3863', '50886abd-184f-4dcf-94d9-e5241d2ad7f3', 'c0023f8f-7077-4f8d-ab9e-db133944b211', 'எங்க அம்மா அப்பா வந்து எங்க மேல ரொம்ப பிரியம். எங்களை எங்கேயும் அனுப்ப மாட்டாங்க, யார் வீட்டுக்கும் அனுப்ப மாட்டாங்க. எங்க தேவைக்கு அவங்களே எல்லாம் செஞ்சு கொடுத்துருவாங்க. எங்க அம்மா அப்பா இல்லாம எங்க') ON CONFLICT DO NOTHING;
