INSERT INTO public.event_sources VALUES ('61c51bf2-bbe3-41ac-80d2-47a5b4facc0d', 'e8b050ff-3024-4380-83d5-5fc62b414757', 'a6e456a1-7bde-4dcd-85b1-6c014f8ad33e', 'பள்ளிக்கு நடந்து தான் போவோம். காலையில போயிட்டு மத்தியானம் சாப்பாட்டுக்கு வீட்டுக்கு வருவோம். வீட்டுக்கு வந்து சாப்பிட்டுட்டு மறுபடியும் மத்தியானம் போனோம்னா சாயங்காலம் வீட்டுக்கு வந்துருவோம். வீட்டுக்க') ON CONFLICT DO NOTHING;
INSERT INTO public.event_sources VALUES ('4150075f-b361-4ede-a3ed-dc2a4ae24988', 'a7243b8e-cec7-4791-9331-f74184929575', '187c023c-a7b3-4124-bbea-3d04617481d5', 'எங்க மாற்றத்தை எல்லா ஆசிரியர்களும் நல்லாத்தான் சொல்லிக் கொடுத்தாங்க. சின்ன வயசுல எலிமெண்ட்ரி சிஎஸ்ஐ பள்ளிக்கூடத்துல அஞ்சாவது வரைக்கும் படிச்சோம். அதுல ஞானசுந்தரம்னு வாத்தியார் நாலாவது வாத்தியார் எங்க ') ON CONFLICT DO NOTHING;
INSERT INTO public.event_sources VALUES ('d598e823-5e08-4380-9276-14dc637b3d8a', 'a7243b8e-cec7-4791-9331-f74184929575', '187c023c-a7b3-4124-bbea-3d04617481d5', 'எங்க மாற்றத்தை எல்லா ஆசிரியர்களும் நல்லாத்தான் சொல்லிக் கொடுத்தாங்க. சின்ன வயசுல எலிமெண்ட்ரி சிஎஸ்ஐ பள்ளிக்கூடத்துல அஞ்சாவது வரைக்கும் படிச்சோம். அதுல ஞானசுந்தரம்னு வாத்தியார் நாலாவது வாத்தியார் எங்க ') ON CONFLICT DO NOTHING;
INSERT INTO public.event_sources VALUES ('b6664115-09ab-4a0a-8175-a01f32d833a0', 'ea77ca68-64de-435f-819a-6d0c6810a8c7', '7cf5ec91-be51-406d-9b1a-614d81ed4629', 'பாலிகார நண்பர் வந்து சுபத்ரா டீச்சர் அவங்க இப்போ காலமாயிட்டாங்க. சரோஜினி டீச்சர் காலமாயிட்டாங்க. அவங்க பொண்ணு உமா என்ன எங்க ஸ்கூல்ல தான் படிச்சு எங்க ஸ்கூலுக்கு இப்போ ஹெட்மாஸ்டர் இருக்கிறாப்ல. அப்புறம') ON CONFLICT DO NOTHING;
INSERT INTO public.event_sources VALUES ('55fbc653-17b2-4ad3-9631-458d649cd92d', 'ea77ca68-64de-435f-819a-6d0c6810a8c7', '7cf5ec91-be51-406d-9b1a-614d81ed4629', 'பாலிகார நண்பர் வந்து சுபத்ரா டீச்சர் அவங்க இப்போ காலமாயிட்டாங்க. சரோஜினி டீச்சர் காலமாயிட்டாங்க. அவங்க பொண்ணு உமா என்ன எங்க ஸ்கூல்ல தான் படிச்சு எங்க ஸ்கூலுக்கு இப்போ ஹெட்மாஸ்டர் இருக்கிறாப்ல. அப்புறம') ON CONFLICT DO NOTHING;
INSERT INTO public.story_drafts VALUES ('a66b9bb0-3305-4555-9faa-7e9ee7a12bb6', '9a064be3-6c1b-4383-a5a9-ec80d5dd5684', 'Shanmugam''s Life Biography — NinaivuKalanjiyam', 'en', 3, '[{"id": "c1", "title": "A Joyful Childhood and Formative Years", "status": "confirmed", "content": "The elder, Shanmugam, often reflects on his early years with deep affection, recalling that his young age was filled with immense happiness. He cherished spending his time with his family and playing with his friends. These beautiful memories remain vivid in his mind to this day. He further describes the town where he grew up as both beautiful and peaceful. The home he grew up in was a place brimming with love and joy, where the simple pleasures of spending time with family and playing with friends were his most beloved activities."}]', 'draft', '2026-10-15 17:22:13.735+05:30', '2026-10-15 17:22:13.735+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.story_drafts VALUES ('61e88006-1fd5-4414-bc7c-4ba5084187d0', '11111111-1111-4111-a111-111111111111', 'Rajeshwari''s Life Biography — NinaivuKalanjiyam', 'en', 3, '[{"id": "c1", "title": "Early Years in Bavanipur", "status": "confirmed", "content": "Her childhood began in Purushamalai before her family relocated to Bavanipur, where she spent her early years on Pazhanipuram Gounder Street, residing in the third street within a thatched house. The home was situated beside a flowing river on both sides, allowing her to assist her mother with daily chores. She would walk to school, return home for her midday meal prepared by her mother, and head back at 1:45 PM. During these formative years, she and her younger sister rarely left the premises, dedicating their time instead to helping their parents at home."}, {"id": "c2", "title": "Education and the Path to Teaching", "status": "confirmed", "content": "She completed her first through fifth grades at the CSI school, followed by her studies at the Boys and Girls High School, where she experienced co-education. Immediately after finishing the eleventh grade, she enrolled in a two-year Teacher Training program at GDS in Erode. Her professional journey commenced in 1972. Her initial teaching post was at the Dip City Palayam Union in Bavanipur. She later worked in Kavunthapadi for about seven years. After failing to secure a position back in Bavanipur, she returned to Dip City Palayam, where she remained for thirty-two years."}, {"id": "c3", "title": "Family Bonds and Upbringing", "status": "confirmed", "content": "Her parents held a deep affection for her and her siblings, rarely sending them to others'' houses and personally fulfilling all their needs. Even when they stepped out, they ensured they returned by evening. She grew up with two older brothers. The elder brother worked as a secretary at the Land Mortgage Bank, while the younger brother was a high school clerk. She shared a close bond with her younger sister, with whom she walked to and from school together. However, due to a lack of space to study, her sister could not continue her education and eventually settled in Salem. The siblings consistently supported their parents at home."}, {"id": "c4", "title": "Daily Life and Childhood Pastimes", "status": "confirmed", "content": "Traveling to school was done entirely on foot. Upon returning home for lunch, she and her sister would fetch water from the well to help their mother before sitting down to study. Lacking electricity at home, their studies were illuminated by kerosene lamps. Traditional outdoor games were not a part of their daily routine. They stayed within the household to assist their parents, only venturing out to play the game of ''Thayakkam'' during the May school holidays."}, {"id": "c5", "title": "Memories of Teachers and Friends", "status": "confirmed", "content": "She recalled all her elementary teachers as good instructors, holding a distinct memory of a fourth-grade teacher named Gnanasundaram. He had reprimanded her severely—striking her on the forehead with a square stick—when she missed school for her elder brother''s wedding, questioning if she too was getting married. Later, the teachers at the Girls High School treated her well. Among her childhood friends, she remembered Subhadra Teacher and Sarojini Teacher, both of whom have since passed away; Sarojini Teacher''s daughter, Uma, is now the headmaster at their alma mater. She also maintained ties with Rukmani, a friend from Kaligarayampalayam who completed Teacher Training, worked as a teacher in Coimbatore, and has since retired. Rukmani later married a man named Easwari, who resides in Kaligarayampalayam, a village located near Bavanipur."}]', 'draft', '2026-10-15 18:11:43.526+05:30', '2026-10-15 18:11:43.526+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.story_drafts VALUES ('2c1f9e8f-f2c2-429f-880b-e314f4810eed', '11111111-1111-4111-a111-111111111111', 'ராஜேஸ்வரி அவர்களின் வாழ்க்கை வரலாறு — நினைவுக் களஞ்சியம்', 'ta', 1, '[{"id": "c1", "title": "குழந்தைப் பருவமும் ஆரம்பகாலக் கல்வியும்", "status": "confirmed", "content": "நான் புருஷாமலத்திலிருந்து பவானிக்கு வந்தேன். சி.எஸ்.ஐ பள்ளிக்கூடத்தில் ஒன்றாம் வகுப்பு முதல் ஐந்தாம் வகுப்பு வரை படித்தோம். பின்னர் பாய்ஸ் உயர்நிலைப் பள்ளி மற்றும் கேர்ள்ஸ் உயர்நிலைப் பள்ளியில் இணைந்து பயின்றோம். பதினொன்றாம் வகுப்பு முடித்தவுடன் ஆசிரியர் பயிற்சிக்குச் சென்றோம். ஈரோட்டில் இரண்டு ஆண்டுகள் ஜி.டி.எஸ்-இல் படித்தேன். 1972-ஆம் ஆண்டில் பணிவாய்ப்பு கிடைத்தது."}, {"id": "c2", "title": "பவானியில் வளர்ந்த நாள்கள்", "status": "confirmed", "content": "நான் வளர்ந்த ஊர் பவானி, பழனிபுரம் கவுண்டர் தெருவில். மூன்றாவது வீதியில் குடியிருந்தோம். எங்கள் வீடு சால வீடு. வீட்டிற்கு இருபுறமும் ஆறு ஓடியது. வீட்டிற்குச் சென்று அனைத்து வேலைகளையும் செய்வோம். எங்கள் தாய்க்கு உதவியாகச் செய்து கொடுத்துவிட்டு, பின்னர் பள்ளிக்கு நடந்து செல்வோம். மதிய உணவிற்குத் தாய் செய்து வைத்திருப்பார். உணவருந்திக்கொண்டு, மதியம் ஒன்றே முக்கால் மணிக்கு பள்ளிக்குச் செல்வோம்."}, {"id": "c3", "title": "சிறுவயது விளையாட்டுகளும் குடும்பப் பொறுப்புகளும்", "status": "confirmed", "content": "பாரம்பரிய விளையாட்டுகளை அவர்கள் கைவிட்டுவிட்டனர். அவர்கள் எங்கும் செல்வதில்லை; வீட்டிலேயே இருக்கின்றனர். தாய்க்கு உதவுபவர்களாக இருக்கின்றனர். வீட்டை விட்டு வெளியே எங்கும் செல்வதில்லை. தாயாட்டம் விளையாடமாட்டீர்களா என்று கேட்டதற்கு, மே மாத விடுமுறையில் மட்டுமே விளையாடுவோம் என்று அவர்கள் தெரிவித்தனர்."}, {"id": "c4", "title": "பெற்றோரின் அன்பும் அரவணைப்பும்", "status": "confirmed", "content": "எங்கள் பெற்றோர் எங்கள் மீது மிகுந்த அன்பு கொண்டிருந்தனர். எங்களை எங்கும் அனுப்ப மாட்டார்கள்; வேறு எவருடைய வீட்டிற்கும் அனுப்ப மாட்டார்கள். எங்கள் தேவைகளை அவர்களே நிறைவேற்றித் தருவார்கள். அவர்கள் இல்லாமல் எங்களால் இயலாது. அவர்கள் காலையில் சென்றுவிட்டு மாலையில் திரும்புவார்கள். தந்தைக்கு என் மீது மிகுந்த அன்பு இருந்தது."}, {"id": "c5", "title": "உடன்பிறப்புகளுடனான உறவு", "status": "confirmed", "content": "எனக்கு இரண்டு சகோதரர்கள் உள்ளனர்; அவர்கள் என்னை விட மூத்தவர்கள். அவர்கள் அனைவரும் கல்வி பயின்று வேலைக்குச் சென்றனர். மூத்த சகோதரர் வங்கியில் செயலாளராகவும், இளைய சகோதரர் உயர்நிலைப் பள்ளியில் எழுத்தராகவும் பணியாற்றினர். எனது தங்கை என்னுடன் பள்ளிக்கூடம் சென்று வந்தாள். ஆனால் நான் கல்வி கற்றதால், அவளுக்குப் படிப்பதற்கு இடமளிக்க இயலவில்லை. அவள் வேலைக்குச் செல்லவில்லை. எனது தங்கை சேலத்தில் வசிக்கிறாள்."}, {"id": "c6", "title": "பள்ளிப் பருவமும் அன்றாடப் பயணமும்", "status": "confirmed", "content": "பள்ளிக்கூடம் செல்வதற்கு நாங்கள் நடந்தே செல்வோம். காலையில் சென்றுவிட்டு, மதிய உணவுக்காக வீட்டிற்கு வருவோம். உணவருந்திய பின்பு மீண்டும் சென்றால், மாலையில் வீட்டிற்குத் திரும்புவோம். வீட்டிற்கு வந்ததும், தாயாருக்கு நீர் தேவைப்படுவதால், கிணற்றுக்குச் சென்று நீரைச் சுமந்து வந்து ஊற்றி வைப்போம். அதன் பிறகு அமர்ந்து படிப்போம். எங்கள் வீட்டில் மின்சார வசதி இல்லை என்பதால், சீமை விளக்கிலேயே நாங்கள் படித்தோம்."}, {"id": "c7", "title": "ஆசிரியர்களின் தாக்கமும் நினைவுகளும்", "status": "confirmed", "content": "அனைத்து ஆசிரியர்களும் சிறப்பாகக் கற்பித்தனர். ஐந்தாம் வகுப்பு வரைக்கும் எலிமெண்டரி சி.எஸ்.ஐ பள்ளிக்கூடத்தில் படித்தோம். அங்கு ஞானசுந்தரம் என்பவர் நான்காம் வகுப்பு ஆசிரியராக இருந்தார். எனது அண்ணனின் திருமணத்திற்காக விடுப்பு எடுத்துவிட்டு அடுத்த நாள் சென்றபோது, அவர் கையில் ஒரு குச்சியுடன் ''எங்க ஏழை'' என்று கேட்டதற்கு, அண்ணனின் திருமணம் என்பதால் என்னால் வர இயலவில்லை என்று கூறியதற்கு, ''நீயும் திருமணம் செய்துகொண்டு செல்கிறாயா'' என்று கையைத் திருப்பி கண்களிலேயே அடித்தார். அந்த நினைவினை நான் இன்னும் மறக்கவில்லை. உயர்நிலைப் பள்ளியில் எஞ்சியிருந்த ஆசிரியர்கள் அனைவரும் மிகச் சிறப்பாக நடந்து கொண்டனர்."}, {"id": "c8", "title": "பள்ளிக் கால நண்பர்கள்", "status": "confirmed", "content": "பாலிகா கார நண்பர்களான சுபத்ரா ஆசிரியை மற்றும் சரோஜினி ஆசிரியை ஆகியோர் தற்போது காலமானார்கள். அவர்களது மகள் உமா, எங்கள் பள்ளிக்கூடத்தில் பயின்றவர்; தற்போது தலைமை ஆசிரியராகப் பணியாற்றி வருகிறார். என்னுடன் பயின்ற தோழி ருக்மணி, காளிங்கராயம்பாளையத்தைச் சேர்ந்தவர். கல்வியை நிறைவு செய்து ஆசிரியர் பயிற்சி முடித்த அவர், கோயம்புத்தூரில் ஆசிரியராகப் பணியாற்றி தற்போது ஓய்வு பெற்றுள்ளார். ஈஸ்வரி என்ற பெண்ணை காளிங்கராயம்பாளையத்தில் திருமணம் செய்துகொண்ட அவர், அங்கேயே வசிக்கிறார். அப்பகுதி பவானிக்கு அருகில் அமைந்துள்ளது."}]', 'draft', '2026-10-15 18:05:53.984+05:30', '2026-10-15 18:40:54.575+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.story_drafts VALUES ('80af46bd-bf27-460c-8ed4-24327c8b7082', '11111111-1111-4111-a111-111111111111', 'ராஜேஸ்வரி அவர்களின் வாழ்க்கை வரலாறு — நினைவுக் களஞ்சியம்', 'ta', 2, '[{"id": "c1", "title": "குழந்தைப் பருவமும் கல்வியும்", "status": "confirmed", "content": "எனது இளமைப் பருவம் புருஷாமலத்திலிருந்து தொடங்கியது. அங்கிருந்து பவானிக்கு வந்தோம். சி.எஸ்.ஐ பள்ளிக்கூடத்தில் ஒன்றாம் வகுப்பு முதல் ஐந்தாம் வகுப்பு வரை படித்தோம். அதன் பிறகு பாய்ஸ் உயர்நிலைப் பள்ளி மற்றும் கேர்ள்ஸ் உயர்நிலைப் பள்ளியில் இணைக்கல்வியாகப் படித்தோம். பதினொன்றாம் வகுப்பு முடித்தவுடன், ஈரோட்டில் உள்ள ஜி.டி.எஸ்-இல் இரண்டு ஆண்டுகள் ஆசிரியர் பயிற்சி பெற்றேன். 1972-ஆம் ஆண்டில் பணி கிடைத்தது. முதலில் திப் சிட்டி பாலையத்தில் ஆசிரியராகப் பணிபுரிந்தேன். பின்னர் கவுந்தப்பாடிக்கு ஏழு ஆண்டுகள் சென்றேன். மீண்டும் பவானியில் முயற்சி செய்து கிடைக்காததால், மீண்டும் திப் சிட்டி பாலையத்திலேயே முப்பத்திரண்டு ஆண்டுகள் பணிபுரிந்தேன்."}, {"id": "c2", "title": "வளர்ந்த ஊரும் வீடும்", "status": "confirmed", "content": "நான் வளர்ந்த ஊர் பவானி, பழனிபுரம் கவுண்டர் தெரு. மூன்றாவது வீதியில் குடியிருந்தோம். எங்கள் வீடு சாலையோர வீடு. ஆத்தின் இருபுறமும் ஆறு ஓடுவதால், நாங்கள் அனைவரும் அங்கேயே படித்து, அனைத்து வேலைகளையும் செய்தோம். எங்கள் தாய்க்கு உதவியாகச் செய்துவிட்டு, பின்னர் பள்ளிக்கூடம் நோக்கி நடந்து செல்வோம். மதிய உணவுக்காகத் தாய் தயாரித்து வைத்திருப்பார். உணவருந்திய பின்னர், மதியம் ஒன்றே முக்கால் மணிக்கு பள்ளிக்கூடம் செல்வோம். வீட்டிற்கு வந்ததும், கிணற்றிலிருந்து நீர் எடுத்து ஊற்றிய பின் அமர்ந்து படிப்போம். எங்கள் வீட்டில் மின்சார வசதி இல்லை. எனவே, சீமை விளக்கிலேயே நாங்கள் படித்தோம்."}, {"id": "c3", "title": "பாரம்பரிய விளையாட்டுகளும் குடும்பப் பிணைப்பும்", "status": "confirmed", "content": "பாரம்பரிய விளையாட்டுகளை நாங்கள் விளையாடுவதில்லை; நாங்கள் எங்கும் வெளியே செல்வதில்லை. வீட்டிலேயே தங்கி தாய்க்கு உதவியாக இருக்கிறோம். நானும் எனது தங்கையும் இணைந்து தந்தைக்கு, தாய்க்கு உதவியாக இருக்கிறோம். வீட்டை விட்டு எங்கும் வெளியே செல்வதில்லை. தாயக்கட்டு விளையாடுகிறீர்களா என்று கேட்டால், மே மாத விடுமுறையின் போது மட்டுமே விளையாடுவோம் என்று கூறுகிறேன். எங்களை எங்கள் பெற்றோர் மிகவும் அன்புடன் நடத்துகிறார்கள். எங்களை எங்கும் அனுப்ப மாட்டார்கள்; வேறு எவருடைய வீட்டிற்கும் அனுப்ப மாட்டார்கள். எங்களின் தேவைகளுக்கான அனைத்தையும் அவர்களே செய்து கொடுக்கிறார்கள். அவர்கள் இல்லாமல் எங்களால் வாழ முடியாது. காலைச் சென்றுவிட்டு மாலை திரும்பி வருவார்கள். அது எங்கள் தந்தைக்கு என் மீது மிகுந்த அன்பிருப்பதைக் காட்டுகிறது."}, {"id": "c4", "title": "உடன்பிறப்புகளுடனான உறவு", "status": "confirmed", "content": "எங்களுக்கு இரண்டு அண்ணன்களும் ஒரு தங்கையும் உண்டு. இருவருமே எனக்கு மூத்தவர்கள். அவர்கள் இருவரும் கல்வி பயின்று வேலை பார்த்து வந்தனர். மூத்த அண்ணன் ஒரு வங்கியில் அடமானத் துறையில் செயலாளராகப் பணியாற்றினார்; இளைய அண்ணன் உயர்நிலைப் பள்ளியில் குமாஸ்தாவாகப் பணியாற்றினார். எனது தங்கையும் நானும் ஒன்றாகப் பள்ளிக்கூடம் சென்று வந்தோம். ஆனால், நான் கல்வி கற்றேன்; அவளுக்குக் கல்வி கற்பதற்கு வாய்ப்பு கிடைக்கவில்லை, எனவே அவள் வேலைக்குச் செல்லவில்லை. அவள் தற்போது சேலத்தில் வசிக்கிறாள்."}, {"id": "c5", "title": "பள்ளிப் பருவமும் ஆசிரியர்களும்", "status": "confirmed", "content": "பள்ளிக்கூடம் நோக்கி நாங்களே நடந்து சென்றோம். காலை வேளையில் சென்றுவிட்டு, மதிய உணவுக்காக வீட்டிற்கு வருவோம். வீட்டிற்கு வந்து உணவு அருந்திவிட்டு மீண்டும் சென்றால், மாலை வேளையில் வீட்டிற்குத் திரும்பி வருவோம். எங்களது மாற்றாந்தாய்மார்கள் அனைவரும் ஆசிரியர்களால் நன்முறையாகக் கற்பிக்கப்பட்டனர். எலிமெண்டரி சி.எஸ்.ஐ பள்ளிக்கூடத்தில் ஐந்தாம் வகுப்பு வரை படித்தோம். அங்கு ஞானசுந்தரம் என்பவர் நான்காம் வகுப்பு ஆசிரியராக இருந்தார். எங்களது அண்ணனின் திருமணத்திற்காக விடுப்பு எடுத்துக்கொண்டு அடுத்த நாள் சென்றபோது, அவர் கையில் ஒரு சதுரமான மரக்கட்டையை வைத்து ''ஏழை'' என்று கேட்டதற்கு, ''உன் அண்ணனின் திருமணம், அதனால் என்னால் வர இயலவில்லை. நீயும் திருமணம் செய்துகொண்டு செல்கிறாயா?'' என்று கூறிவிட்டு, கண்களிலேயே அடித்தார். இன்னும் எனக்கு அந்த நினைவிருக்கிறது. உயர்நிலைப் பள்ளியில் ஆசிரியர்கள் அனைவரும் நன்முறையாகவே நடந்து கொண்டனர்."}, {"id": "c6", "title": "நினைவில் நிற்கும் பால்ய கால நண்பர்கள்", "status": "confirmed", "content": "பால்கார நண்பரான சுபத்ரா ஆசிரியை தற்போது காலமானார். சரோஜினி ஆசிரியை காலமானார். அவர்களின் மகள் உமா எங்கள் பள்ளிக்கூடத்தில் பயின்றார்; தற்போது தலைமை ஆசிரியராகப் பணியாற்றுவதாக அறியப்படுகிறார். என்னுடன் பயின்ற தோழியான காளிங்கராயம்பாளையத்தைச் சேர்ந்த ருக்மணி, தனது கல்வியை முடித்து ஆசிரியர் பயிற்சிப் படிப்பை முடித்துள்ளார். பின்னர் கோயம்புத்தூரில் ஆசிரியராகப் பணியாற்றி தற்போது ஓய்வு பெற்றுள்ளார். ஈஸ்வரி என்ற ஒரு பெண்ணை காளிங்கராயம்பாளையத்தில் திருமணம் செய்து கொடுத்துள்ளோம்; அவர் அங்கேயே வசிக்கிறார். காளிங்கராயம்பாளையம் பவானிக்கு அருகில் அமைந்துள்ளது."}]', 'draft', '2026-10-15 18:11:34.986+05:30', '2026-10-15 18:11:34.986+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.story_drafts VALUES ('2a54a490-0254-49fa-8fa7-be50b162a010', '9a064be3-6c1b-4383-a5a9-ec80d5dd5684', 'சண்முகம் அவர்களின் வாழ்க்கை வரலாறு — நினைவுக் களஞ்சியம்', 'ta', 1, '[{"id": "c1", "title": "சிறுவயதும் மகிழ்ச்சியான நினைவுகளும்", "status": "confirmed", "content": "சண்முகம் அவர்களின் இளமைக்காலம் மிகவும் மகிழ்ச்சியானதாக அமைந்திருந்தது. அக்காலகட்டத்தில் நண்பர்களுடன் விளையாடுவதும், குடும்பத்தினருடன் நேரம் செலவிடுவதும் அவருக்கு மிகவும் விருப்பமானவையாக இருந்தன. அந்த இனிமையான நினைவுகள் இன்றும் அவரது உள்ளத்தில் நிலைத்து நிற்கின்றன."}, {"id": "c2", "title": "வளர்ந்த ஊரும் அன்பான வீடும்", "status": "confirmed", "content": "சண்முகம் அவர்கள் வளர்ந்த ஊர் மிகவும் அழகாகவும் அமைதியாகவும் இருந்தது. அவர் வாழ்ந்த வீடு அன்பும் மகிழ்ச்சியும் நிறைந்ததாக இருந்தது. மேலும், குடும்பத்தினருடன் நேரம் செலவிடுவதும் நண்பர்களுடன் விளையாடுவதும் அவருக்கு மிகவும் விருப்பமானவையாகத் தொடர்ந்தன."}]', 'draft', '2026-10-15 17:16:42.958+05:30', '2026-10-15 17:16:42.958+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.story_drafts VALUES ('0e0e00b9-4416-4cc7-9a00-55b286f55d5e', '9a064be3-6c1b-4383-a5a9-ec80d5dd5684', 'சண்முகம் அவர்களின் வாழ்க்கை வரலாறு — நினைவுக் களஞ்சியம்', 'ta', 2, '[{"id": "c1", "title": "சிறுவயதும் மகிழ்ச்சி நிறைந்த நாட்களும்", "status": "confirmed", "content": "சண்முகம் அவர்களின் இளமைப் பருவம் மிகவும் மகிழ்ச்சிகரமானதாக அமைந்திருந்தது. அக்காலகட்டத்தில் நண்பர்களுடன் விளையாடுவதும், குடும்பத்தினருடன் நேரம் செலவிடுவதும் அவருக்கு மிகவும் விருப்பமானவையாக இருந்தன. அந்த இனிய நினைவுகள் இன்றும் அவரது உள்ளத்தில் ஆழமாக நிலைத்திருக்கின்றன."}, {"id": "c2", "title": "அமைதியான ஊரும் அன்பான இல்லமும்", "status": "confirmed", "content": "சண்முகம் அவர்கள் வளர்ந்த ஊர் மிகவும் அழகானதும் அமைதியானதுமாக இருந்தது. அவர் வாழ்ந்த வீடு அன்பும் மகிழ்ச்சியும் நிறைந்தது. அங்கு குடும்பத்தினருடன் நேரம் செலவிடுவதும், நண்பர்களுடன் விளையாடுவதும் அவருக்கு மிகவும் விருப்பமானவையாக அமைந்தன."}]', 'draft', '2026-10-15 17:22:08.001+05:30', '2026-10-15 17:22:08.001+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.story_drafts VALUES ('e04afba7-3361-4b72-b2de-998c30b578ed', 'b2fb1996-e24c-405a-9895-979096e2df22', 'Senthil Kumar அவர்களின் வாழ்க்கை வரலாறு — நினைவுக் களஞ்சியம்', 'ta', 1, '[{"id": "c1", "title": "இன்பமயமான குழந்தைப் பருவம்", "status": "confirmed", "content": "எனது சிறுவயதுக் காலம் மிகவும் மகிழ்ச்சி நிறைந்ததாகவும், இன்பகரமானதாகவும் அமைந்திருந்தது. குடும்பத்தினருடன் நேரத்தைச் செலவழிப்பதும், நண்பர்களுடன் இணைந்து விளையாடி மகிழ்வதுமாக எனது குழந்தைப் பருவம் இனிமையான அழகிய நினைவுகளால் நிறைந்திருந்தது."}]', 'draft', '2026-10-22 20:34:54.335342+05:30', '2026-10-22 20:34:54.335342+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.story_drafts VALUES ('69203b64-53e8-4ff9-8158-37ae99c9188c', 'b2fb1996-e24c-405a-9895-979096e2df22', 'Senthil Kumar''s Life Biography — NinaivuKalanjiyam', 'en', 3, '[{"id": "c1", "title": "A childhood filled with happiness", "status": "confirmed", "content": "Mr. Senthil Kumar''s childhood was filled with immense joy and fulfillment. His early years were spent delightfully, sharing precious time with his loving family and enthusiastically playing with his childhood friends. All such moments remain etched deep within his heart as beautiful, everlasting memories."}]', 'draft', '2026-10-22 20:36:07.722477+05:30', '2026-10-23 18:23:53.928712+05:30') ON CONFLICT DO NOTHING;
INSERT INTO public.story_drafts VALUES ('35cd03db-9c8e-4066-9172-88eade82c988', 'b2fb1996-e24c-405a-9895-979096e2df22', 'Senthil Kumar''s Life Biography — NinaivuKalanjiyam', 'en', 2, '[{"id": "c1", "title": "A joy-filled childhood", "status": "confirmed", "content": "Mr. Senthil Kumar’s childhood was filled with immense joy and contentment. His early years were enriched with beautiful memories of spending precious time with his beloved family and joyfully playing with dear friends. Surrounded by love and companionship, those moments remain etched in his heart as everlasting golden memories."}]', 'draft', '2026-10-22 20:35:49.49496+05:30', '2026-10-23 18:24:05.030334+05:30') ON CONFLICT DO NOTHING;
